window.casadiExamples = {
  "accessing_mx_algorithm.js": "//\n//     MIT No Attribution\n//\n//     Copyright (C) 2010-2023 Joel Andersson, Joris Gillis, Moritz Diehl, KU Leuven.\n//\n//     Permission is hereby granted, free of charge, to any person obtaining a copy of this\n//     software and associated documentation files (the \"Software\"), to deal in the Software\n//     without restriction, including without limitation the rights to use, copy, modify,\n//     merge, publish, distribute, sublicense, and/or sell copies of the Software, and to\n//     permit persons to whom the Software is furnished to do so.\n//\n//     THE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED,\n//     INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A\n//     PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT\n//     HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION\n//     OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE\n//     SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.\n//\n//\n// JS port of docs/examples/python/accessing_mx_algorithm.py.\n//\n// Demonstrates how the algorithm of an MX Function can be accessed and\n// its atomic operations traversed.  Unlike the SX variant, the work\n// vector holds matrices; here we keep them as DM and use casadi's\n// free-function arithmetic instead of numpy.\n//\n// JS notes (see README.md):\n//   * Opcode enums (M.Operation.OP_*) and instruction_id() are both\n//     bigint -- compare directly with `===`.\n//   * MX has no to_DM(); evaluate a constant node with M.evalf(mx) -> DM.\n//   * Element-wise * is M.times; matrix product is M.mtimes.\n\nasync function example(M, log) {\n  const OP = M.Operation;\n  const dm = (v) => \"[\" + v.nonzeros().join(\", \") + \"]\";\n\n  // Create a function:  r = 3*(c @ b)*a + b\n  const a = M.MX.sym(\"a\");\n  const b = M.MX.sym(\"b\", 2);\n  const c = M.MX.sym(\"c\", 2, 2);\n  const r = M.plus(M.times(M.times(M.MX(3), M.mtimes(c, b)), a), b);\n  const f = new M.Function(\"f\", [a, b, c], [r], [\"a\", \"b\", \"c\"], [\"r\"]);\n\n  // Input values of matching dimensions\n  const input_val = [\n    M.DM([2.0]),\n    M.DM([3.0, 4.0]),\n    M.DM([[5.0, 1.0], [8.0, 4.0]]),\n  ];\n  const output_val = [M.DM.zeros(2)];\n\n  // Work vector\n  const work = new Array(Number(f.sz_w())).fill(null);\n\n  const n = Number(f.n_instructions());\n  for (let k = 0; k < n; ++k) {\n    const op = f.instruction_id(k);\n    const o = f.instruction_output(k);\n    const i = f.instruction_input(k);\n\n    if (op === OP.OP_CONST) {\n      const v = M.evalf(f.instruction_MX(k));\n      work[o[0]] = v;\n      log(`work[${o[0]}] = ${dm(v)}`);\n    } else if (op === OP.OP_INPUT) {\n      work[o[0]] = input_val[i[0]];\n      log(`work[${o[0]}] = input[${i[0]}]            ---> ${dm(work[o[0]])}`);\n    } else if (op === OP.OP_OUTPUT) {\n      output_val[o[0]] = work[i[0]];\n      log(`output[${o[0]}] = work[${i[0]}]             ---> ${dm(output_val[o[0]])}`);\n    } else if (op === OP.OP_ADD) {\n      work[o[0]] = M.plus(work[i[0]], work[i[1]]);\n      log(`work[${o[0]}] = work[${i[0]}] + work[${i[1]}]      ---> ${dm(work[o[0]])}`);\n    } else if (op === OP.OP_MUL) {\n      work[o[0]] = M.times(work[i[0]], work[i[1]]);\n      log(`work[${o[0]}] = work[${i[0]}] * work[${i[1]}]        ---> ${dm(work[o[0]])}`);\n    } else if (op === OP.OP_MTIMES) {\n      work[o[0]] = M.plus(M.mtimes(work[i[1]], work[i[2]]), work[i[0]]);\n      log(`work[${o[0]}] = work[${i[1]}] @ work[${i[2]}] + work[${i[0]}]        ---> ${dm(work[o[0]])}`);\n    } else {\n      throw new Error(\"Unknown operation id \" + op + \" at instruction \" + k);\n    }\n  }\n\n  log(\"------\");\n  log(\"Evaluated \" + f.str());\n  log(\"Expected: \" + dm(f.call(input_val)[0]));\n  log(\"Got:      \" + dm(output_val[0]));\n}\n\nif (typeof require !== \"undefined\" && typeof module !== \"undefined\" && require.main === module) {\n  const path = require(\"path\");\n  const casadiPath = process.env.CASADI_JS\n    || path.resolve(__dirname, \"../../../build-wasm/swig/wasm-js/casadi.js\");\n  require(casadiPath)()\n    .then((M) => example(M, (...a) => console.log(...a)))\n    .catch((e) => { console.error(\"FATAL:\", e.message || e); process.exit(1); });\n}\n\nif (typeof module !== \"undefined\" && module.exports) module.exports = example;\n",
  "accessing_sx_algorithm.js": "//\n//     MIT No Attribution\n//\n//     Copyright (C) 2010-2023 Joel Andersson, Joris Gillis, Moritz Diehl, KU Leuven.\n//\n//     Permission is hereby granted, free of charge, to any person obtaining a copy of this\n//     software and associated documentation files (the \"Software\"), to deal in the Software\n//     without restriction, including without limitation the rights to use, copy, modify,\n//     merge, publish, distribute, sublicense, and/or sell copies of the Software, and to\n//     permit persons to whom the Software is furnished to do so.\n//\n//     THE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED,\n//     INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A\n//     PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT\n//     HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION\n//     OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE\n//     SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.\n//\n//\n// JS port of docs/examples/python/accessing_sx_algorithm.py.\n//\n// Demonstrates how the algorithm of an SX Function can be accessed and\n// its atomic operations traversed, re-evaluating it by hand.\n//\n// JS notes (see README.md):\n//   * Opcode enums (M.Operation.OP_*) and instruction_id() are both\n//     bigint, so compare them directly with `===`.\n//   * instruction_output(k) / instruction_input(k) return number[].\n//   * sz_w() / n_instructions() are bigint -> wrap with Number() for loops.\n\nasync function example(M, log) {\n  const OP = M.Operation;\n\n  // Create a function\n  const a = M.SX.sym(\"a\");\n  const b = M.SX.sym(\"b\", 2);\n  const f = new M.Function(\"f\", [a, b], [M.plus(M.times(M.SX(2), a), b)], [\"a\", \"b\"], [\"r\"]);\n\n  // Input / output values of matching dimensions\n  const input_val = [[2.0], [3.0, 4.0]];\n  const output_val = [[0.0, 0.0]];\n\n  // Work vector\n  const work = new Array(Number(f.sz_w())).fill(0);\n\n  // Loop over the algorithm\n  const n = Number(f.n_instructions());\n  for (let k = 0; k < n; ++k) {\n    const op = f.instruction_id(k);\n    const o = f.instruction_output(k);\n    const i = f.instruction_input(k);\n\n    if (op === OP.OP_CONST) {\n      work[o[0]] = f.instruction_constant(k);\n      log(`work[${o[0]}] = ${work[o[0]]}`);\n    } else if (op === OP.OP_INPUT) {\n      work[o[0]] = input_val[i[0]][i[1]];\n      log(`work[${o[0]}] = input[${i[0]}][${i[1]}]            ---> ${work[o[0]]}`);\n    } else if (op === OP.OP_OUTPUT) {\n      output_val[o[0]][o[1]] = work[i[0]];\n      log(`output[${o[0]}][${o[1]}] = work[${i[0]}]             ---> ${output_val[o[0]][o[1]]}`);\n    } else if (op === OP.OP_TWICE) {\n      work[o[0]] = 2 * work[i[0]];\n      log(`work[${o[0]}] = 2*work[${i[0]}]                         ---> ${work[o[0]]}`);\n    } else if (op === OP.OP_ADD) {\n      work[o[0]] = work[i[0]] + work[i[1]];\n      log(`work[${o[0]}] = work[${i[0]}] + work[${i[1]}]        ---> ${work[o[0]]}`);\n    } else if (op === OP.OP_MUL) {\n      work[o[0]] = work[i[0]] * work[i[1]];\n      log(`work[${o[0]}] = work[${i[0]}] * work[${i[1]}]        ---> ${work[o[0]]}`);\n    } else {\n      throw new Error(\"Unknown operation id \" + op + \" at instruction \" + k);\n    }\n  }\n\n  log(\"------\");\n  log(\"Evaluated \" + f.str());\n  log(\"Expected: \" + f.call([M.DM(input_val[0]), M.DM(input_val[1])])[0].nonzeros().join(\" \"));\n  log(\"Got:      \" + output_val[0].join(\" \"));\n}\n\nif (typeof require !== \"undefined\" && typeof module !== \"undefined\" && require.main === module) {\n  const path = require(\"path\");\n  const casadiPath = process.env.CASADI_JS\n    || path.resolve(__dirname, \"../../../build-wasm/swig/wasm-js/casadi.js\");\n  require(casadiPath)()\n    .then((M) => example(M, (...a) => console.log(...a)))\n    .catch((e) => { console.error(\"FATAL:\", e.message || e); process.exit(1); });\n}\n\nif (typeof module !== \"undefined\" && module.exports) module.exports = example;\n",
  "biegler_10_1.js": "//\n//     MIT No Attribution\n//\n//     Copyright (C) 2010-2023 Joel Andersson, Joris Gillis, Moritz Diehl, KU Leuven.\n//\n//     Permission is hereby granted, free of charge, to any person obtaining a copy of this\n//     software and associated documentation files (the \"Software\"), to deal in the Software\n//     without restriction, including without limitation the rights to use, copy, modify,\n//     merge, publish, distribute, sublicense, and/or sell copies of the Software, and to\n//     permit persons to whom the Software is furnished to do so.\n//\n//     THE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED,\n//     INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A\n//     PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT\n//     HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION\n//     OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE\n//     SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.\n//\n//\n// JS port of docs/examples/python/biegler_10_1.py.\n//\n// Exercise 1, chapter 10 from Larry Biegler's book: orthogonal collocation\n// applied to a scalar ODE, solved as an NLP with ipopt for N = 1..10 elements.\n//\n// JS notes (see README.md):\n//   * Collocation coefficients C/D are computed numerically (Function eval)\n//     into plain JS arrays so they can be indexed directly.\n//   * The collocated states Z are kept as a JS [i][j] grid of scalar SX\n//     symbols; x is their column-major vectorisation (vec(Z.T)).\n//   * Plotting is dropped; the optimal cost + solution are logged instead.\n\nasync function example(M, log) {\n  for (let N = 1; N <= 10; ++N) {\n    log(\"N = \" + N);\n\n    // Degree of interpolating polynomial\n    const K = 2;\n\n    // Legendre roots\n    const tau_root = [0.0, 0.211325, 0.788675];\n\n    // Differential equation  dz/dt = z^2 - 2z + 1\n    const z = M.SX.sym(\"z\");\n    const F = new M.Function(\"dz_dt\", [z], [M.plus(M.minus(M.times(z, z), M.times(2, z)), 1)]);\n\n    const z0 = -3;\n\n    // Collocation point and step size\n    const tau = M.SX.sym(\"tau\");\n    const h = 1.0 / N;\n\n    // Coefficients of continuity (D) and collocation (C) equations\n    const D = new Array(K + 1).fill(0);\n    const C = Array.from({ length: K + 1 }, () => new Array(K + 1).fill(0));\n    for (let j = 0; j <= K; ++j) {\n      let L = M.SX(1);\n      for (let k = 0; k <= K; ++k) {\n        if (k !== j) {\n          L = M.times(L, M.rdivide(M.minus(tau, tau_root[k]), tau_root[j] - tau_root[k]));\n        }\n      }\n      const lfcn = new M.Function(\"lfcn\", [tau], [L]);\n      D[j] = lfcn.call([M.DM(1.0)])[0].nonzeros()[0];\n\n      const tfcn = new M.Function(\"tfcn\", [tau], [M.tangent(L, tau)]);\n      for (let k = 0; k <= K; ++k) {\n        C[j][k] = tfcn.call([M.DM(tau_root[k])])[0].nonzeros()[0];\n      }\n    }\n\n    // Collocated states as an [i][j] grid of scalar symbols\n    const Z = Array.from({ length: N }, (_, i) =>\n      Array.from({ length: K + 1 }, (_, j) => M.SX.sym(\"Z_\" + i + \"_\" + j)));\n\n    // x = vec(Z.T): column-major, i.e. row i then column j\n    const xparts = [];\n    for (let i = 0; i < N; ++i) for (let j = 0; j <= K; ++j) xparts.push(Z[i][j]);\n    const x = M.vertcat.apply(null, xparts);\n\n    // Construct the NLP constraints\n    const g = [];\n    for (let i = 0; i < N; ++i) {\n      for (let k = 1; k <= K; ++k) {\n        let rhs = M.SX(0);\n        for (let j = 0; j <= K; ++j) rhs = M.plus(rhs, M.times(Z[i][j], C[j][k]));\n        const FF = F.call([Z[i][k]])[0];\n        g.push(M.minus(M.times(h, FF), rhs));\n      }\n      let rhs = M.SX(0);\n      for (let j = 0; j <= K; ++j) rhs = M.plus(rhs, M.times(D[j], Z[i][j]));\n      if (i < N - 1) g.push(M.minus(Z[i + 1][0], rhs));\n    }\n    const gv = M.vertcat.apply(null, g);\n\n    // NLP: minimize x[0]^2 s.t. collocation/continuity equations\n    const nlp = { x: x, f: M.power(xparts[0], 2), g: gv };\n\n    const solver = M.nlpsol(\"solver\", \"ipopt\", nlp, { \"ipopt.tol\": 1e-10, \"ipopt.print_level\": 0, print_time: false });\n\n    const n = Number(x.nnz());\n    const lbx = new Array(n).fill(-100);\n    const ubx = new Array(n).fill(100);\n    lbx[0] = ubx[0] = z0;\n\n    const res = solver.call({\n      x0: M.DM.zeros(n),\n      lbx: M.DM(lbx),\n      ubx: M.DM(ubx),\n      lbg: M.DM(0),\n      ubg: M.DM(0),\n    });\n\n    log(\"  optimal cost: \" + res[\"f\"].nonzeros()[0]);\n    log(\"  optimal solution: [\" + res[\"x\"].nonzeros().map((v) => v.toFixed(4)).join(\", \") + \"]\");\n  }\n}\n\nif (typeof require !== \"undefined\" && typeof module !== \"undefined\" && require.main === module) {\n  const path = require(\"path\");\n  const casadiPath = process.env.CASADI_JS\n    || path.resolve(__dirname, \"../../../build-wasm/swig/wasm-js/casadi.js\");\n  require(casadiPath)()\n    .then((M) => example(M, (...a) => console.log(...a)))\n    .catch((e) => { console.error(\"FATAL:\", e.message || e); process.exit(1); });\n}\n\nif (typeof module !== \"undefined\" && module.exports) module.exports = example;\n",
  "blank.js": "// Write a CasADi script here.\n// Available globals: ca, print.\n\nconst x = ca.MX.sym(\"x\");\nprint(\"x =\", x);\n",
  "c_code_generation.js": "//\n//     MIT No Attribution\n//\n//     Copyright (C) 2010-2023 Joel Andersson, Joris Gillis, Moritz Diehl, KU Leuven.\n//\n//     Permission is hereby granted, free of charge, to any person obtaining a copy of this\n//     software and associated documentation files (the \"Software\"), to deal in the Software\n//     without restriction, including without limitation the rights to use, copy, modify,\n//     merge, publish, distribute, sublicense, and/or sell copies of the Software, and to\n//     permit persons to whom the Software is furnished to do so.\n//\n//     THE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED,\n//     INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A\n//     PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT\n//     HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION\n//     OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE\n//     SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.\n//\n//\n// JS port of docs/examples/python/c_code_generation.py.\n//\n// Generates C source for the gradient of a 7x7 determinant.  The Python\n// version then compiles that C with gcc and loads it back via external();\n// that part is dropped here -- the wasm runtime has no C compiler, so we\n// only demonstrate CodeGenerator.dump() (the generated source text) plus a\n// direct numeric evaluation of the function.\n//\n// JS notes (see README.md):\n//   * CodeGenerator(name).add(f).dump() returns the C source as a string.\n//   * n_nodes() returns bigint -> Number() for arithmetic/printing.\n\nasync function example(M, log) {\n  // Expression for the gradient of the determinant of a 7x7 matrix\n  const x = M.SX.sym(\"x\", 7, 7);\n  const gd = M.gradient(M.det(x), x);\n\n  // Form a function\n  const name = \"grad_det\";\n  const grad_det = new M.Function(name, [x], [gd], [\"x\"], [\"gd\"]);\n\n  // Generate C code (returned as text -- not compiled/loaded here)\n  const cg = new M.CodeGenerator(name + \".c\");\n  cg.add(grad_det);\n  const code = cg.dump();\n  log(\"generated C source for '\" + name + \"': \" + code.length + \" characters\");\n  log(\"--- first lines ---\");\n  log(code.split(\"\\n\").slice(0, 10).join(\"\\n\"));\n  log(\"...\");\n\n  // Number of elementary operations\n  const num_op = Number(grad_det.n_nodes());\n  log(\"number of elementary operations: \" + num_op);\n\n  // Evaluate numerically at a random point\n  const x0 = M.DM.rand(7, 7);\n  const r = grad_det.call([x0])[0];\n  log(\"result (first 7 entries): [\" + r.nonzeros().slice(0, 7).map((v) => v.toFixed(6)).join(\", \") + \", ...]\");\n}\n\nif (typeof require !== \"undefined\" && typeof module !== \"undefined\" && require.main === module) {\n  const path = require(\"path\");\n  const casadiPath = process.env.CASADI_JS\n    || path.resolve(__dirname, \"../../../build-wasm/swig/wasm-js/casadi.js\");\n  require(casadiPath)()\n    .then((M) => example(M, (...a) => console.log(...a)))\n    .catch((e) => { console.error(\"FATAL:\", e.message || e); process.exit(1); });\n}\n\nif (typeof module !== \"undefined\" && module.exports) module.exports = example;\n",
  "chain_qp.js": "//\n//     MIT No Attribution\n//\n//     Copyright (C) 2010-2023 Joel Andersson, Joris Gillis, Moritz Diehl, KU Leuven.\n//\n//     Permission is hereby granted, free of charge, to any person obtaining a copy of this\n//     software and associated documentation files (the \"Software\"), to deal in the Software\n//     without restriction, including without limitation the rights to use, copy, modify,\n//     merge, publish, distribute, sublicense, and/or sell copies of the Software, and to\n//     permit persons to whom the Software is furnished to do so.\n//\n//     THE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED,\n//     INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A\n//     PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT\n//     HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION\n//     OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE\n//     SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.\n//\n//\n// JS port of docs/examples/python/chain_qp.py.\n//\n// Hanging chain of N masses joined by N-1 springs; the equilibrium minimises\n// the total potential energy subject to piecewise-linear ground constraints.\n// Solved as a QP with qpoases.\n//\n// JS notes (see README.md):\n//   * Python's `inf` becomes JS `Infinity`.\n//   * Each (y_i, z_i) is a scalar SX symbol kept in JS arrays; the variable\n//     vector and constraints are assembled with vertcat.\n//   * Plotting is dropped; the optimal cost and a few coordinates are logged.\n\nasync function example(M, log) {\n  // Constants\n  const N = 40;\n  const m_i = 40.0 / N;\n  const D_i = 70.0 * N;\n  const g0 = 9.81;\n  const zmin = 0.5; // ground\n\n  let Vchain = M.SX(0);\n  const x = [];\n  const lbx = [];\n  const ubx = [];\n  const g = [];\n  const lbg = [];\n  const ubg = [];\n\n  let y_prev = null, z_prev = null;\n  for (let i = 1; i <= N; ++i) {\n    const y_i = M.SX.sym(\"y_\" + i);\n    const z_i = M.SX.sym(\"z_\" + i);\n    x.push(y_i, z_i);\n\n    if (i === 1) { lbx.push(-2.0, 1.0); ubx.push(-2.0, 1.0); }\n    else if (i === N) { lbx.push(2.0, 1.0); ubx.push(2.0, 1.0); }\n    else { lbx.push(-Infinity, zmin); ubx.push(Infinity, Infinity); }\n\n    if (i > 1) {\n      Vchain = M.plus(Vchain,\n        M.times(D_i / 2,\n          M.plus(M.power(M.minus(y_prev, y_i), 2), M.power(M.minus(z_prev, z_i), 2))));\n    }\n    Vchain = M.plus(Vchain, M.times(g0 * m_i, z_i));\n\n    // Slanted ground constraint:  z_i - 0.1*y_i >= 0.5\n    g.push(M.minus(z_i, M.times(0.1, y_i)));\n    lbg.push(0.5);\n    ubg.push(Infinity);\n\n    y_prev = y_i; z_prev = z_i;\n  }\n\n  // Formulate and solve the QP\n  const qp = { x: M.vertcat.apply(null, x), f: Vchain, g: M.vertcat.apply(null, g) };\n  const solver = M.qpsol(\"solver\", \"qpoases\", qp, { sparse: true, printLevel: \"none\" });\n\n  const sol = solver.call({\n    lbx: M.DM(lbx), ubx: M.DM(ubx), lbg: M.DM(lbg), ubg: M.DM(ubg),\n  });\n\n  const xopt = sol[\"x\"].nonzeros();\n  log(\"f_opt = \" + sol[\"f\"].nonzeros()[0]);\n\n  // Retrieve coordinates (even -> y, odd -> z)\n  const Y = xopt.filter((_, k) => k % 2 === 0);\n  const Z = xopt.filter((_, k) => k % 2 === 1);\n  log(\"first mass (y, z) = (\" + Y[0].toFixed(4) + \", \" + Z[0].toFixed(4) + \")\");\n  const mid = Math.floor(N / 2);\n  log(\"middle mass (y, z) = (\" + Y[mid].toFixed(4) + \", \" + Z[mid].toFixed(4) + \")\");\n  log(\"last mass (y, z) = (\" + Y[N - 1].toFixed(4) + \", \" + Z[N - 1].toFixed(4) + \")\");\n}\n\nif (typeof require !== \"undefined\" && typeof module !== \"undefined\" && require.main === module) {\n  const path = require(\"path\");\n  const casadiPath = process.env.CASADI_JS\n    || path.resolve(__dirname, \"../../../build-wasm/swig/wasm-js/casadi.js\");\n  require(casadiPath)()\n    .then((M) => example(M, (...a) => console.log(...a)))\n    .catch((e) => { console.error(\"FATAL:\", e.message || e); process.exit(1); });\n}\n\nif (typeof module !== \"undefined\" && module.exports) module.exports = example;\n",
  "dae_collocation.js": "//\n//     MIT No Attribution\n//\n//     Copyright (C) 2010-2023 Joel Andersson, Joris Gillis, Moritz Diehl, KU Leuven.\n//\n//     Permission is hereby granted, free of charge, to any person obtaining a copy of this\n//     software and associated documentation files (the \"Software\"), to deal in the Software\n//     without restriction, including without limitation the rights to use, copy, modify,\n//     merge, publish, distribute, sublicense, and/or sell copies of the Software, and to\n//     permit persons to whom the Software is furnished to do so.\n//\n//     THE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED,\n//     INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A\n//     PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT\n//     HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION\n//     OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE\n//     SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.\n//\n//\n// JS port of docs/examples/python/dae_collocation.py.\n//\n// Hand-built direct collocation of a crane/pendulum DAE optimal control\n// problem (Mario Zanon & Sebastien Gross, KU Leuven 2012), solved as one\n// big NLP with ipopt.  No integrator plugin is used -- the collocation\n// equations are assembled by hand -- so this ports directly.  The original\n// ipopt option linear_solver='ma27' is dropped (default mumps is used) and\n// ipopt.max_iter is left at its default (see the note near the solve).\n//\n// JS notes (see README.md):\n//   * numpy linear algebra (inv, @) is replaced by casadi DM ops (M.inv,\n//     M.mtimes).  Collocation coefficients C/D are plain JS arrays.\n//   * The NLP vector V is sliced via per-scalar vertsplit + range vertcat.\n//   * Plotting is dropped; the optimal cost and a few state samples logged.\n\nasync function example(M, log) {\n  const inf = Infinity;\n\n  // -------- Collocation setup --------\n  const nicp = 1;\n  const xref = 0.1;\n  const l = 1.0, mmass = 1.0, Mmass = 1.0, g = 9.81;\n  const tf = 5.0;\n  const nk = 50;\n  const ndstate = 6, nastate = 1, ninput = 1;\n  const deg = 4;\n  const h = tf / nk / nicp;\n\n  const tau = M.SX.sym(\"tau\");\n  const tau_root = [0].concat(M.collocation_points(deg, \"radau\"));\n\n  // Lagrange-polynomial collocation coefficients\n  const C = Array.from({ length: deg + 1 }, () => new Array(deg + 1).fill(0));\n  const D = new Array(deg + 1).fill(0);\n  for (let j = 0; j <= deg; ++j) {\n    let L = M.SX(1);\n    for (let j2 = 0; j2 <= deg; ++j2) {\n      if (j2 !== j) L = M.times(L, M.rdivide(M.minus(tau, tau_root[j2]), tau_root[j] - tau_root[j2]));\n    }\n    const lfcn = new M.Function(\"lfcn\", [tau], [L]);\n    D[j] = lfcn.call([M.DM(1.0)])[0].nonzeros()[0];\n    const tfcn = new M.Function(\"tfcn\", [tau], [M.tangent(L, tau)]);\n    for (let j2 = 0; j2 <= deg; ++j2) C[j][j2] = tfcn.call([M.DM(tau_root[j2])])[0].nonzeros()[0];\n  }\n\n  // -------- Model setup (implicit DAE) --------\n  const t = M.SX.sym(\"t\");\n  const u = M.SX.sym(\"u\");\n  const xd = M.SX.sym(\"xd\", ndstate);\n  const xa = M.SX.sym(\"xa\", nastate);\n  const xddot = M.SX.sym(\"xdot\", ndstate);\n  const p = M.SX.sym(\"p\", 0, 1);\n\n  const [x, y, w, dx, dy, dw] = M.vertsplit(xd);\n  const [xa0] = M.vertsplit(xa);\n  const xdd = M.vertsplit(xddot);\n\n  const res = M.vertcat(\n    M.minus(xdd[0], dx),\n    M.minus(xdd[1], dy),\n    M.minus(xdd[2], dw),\n    M.plus(M.times(mmass, xdd[3]), M.times(M.minus(x, w), xa0)),\n    M.minus(M.plus(M.times(mmass, xdd[4]), M.times(y, xa0)), g * mmass),\n    M.plus(M.plus(M.times(Mmass, xdd[5]), M.times(M.minus(w, x), xa0)), u),\n    M.plus(M.plus(M.plus(\n      M.times(M.minus(x, w), M.minus(xdd[3], xdd[5])),\n      M.times(y, xdd[4])),\n      M.times(dy, dy)),\n      M.times(M.minus(dx, dw), M.minus(dx, dw))));\n\n  const ffcn = new M.Function(\"ffcn\", [t, xddot, xd, xa, u, p], [res]);\n  const MayerTerm = new M.Function(\"mayer\", [t, xd, xa, u, p],\n    [M.plus(M.plus(M.plus(\n      M.times(M.minus(x, xref), M.minus(x, xref)),\n      M.times(M.minus(w, xref), M.minus(w, xref))),\n      M.times(dx, dx)), M.times(dy, dy))]);\n  const LagrangeTerm = new M.Function(\"lagrange\", [t, xd, xa, u, p],\n    [M.plus(\n      M.times(M.minus(x, xref), M.minus(x, xref)),\n      M.times(M.minus(w, xref), M.minus(w, xref)))]);\n\n  // Bounds\n  const u_min = [-2], u_max = [2];\n  const xD_min = [-inf, -inf, -inf, -inf, -inf, -inf];\n  const xD_max = [inf, inf, inf, inf, inf, inf];\n  const xDi_min = [0.0, l, 0.0, 0.0, 0.0, 0.0];\n  const xDi_max = [0.0, l, 0.0, 0.0, 0.0, 0.0];\n  const xD_init = [0.0, l, 0.0, 0.0, 0.0, 0.0];\n  const xA_min = [-inf], xA_max = [inf];\n  const xA_init = [Math.sign(l) * 9.81];\n\n  // -------- NLP variable layout --------\n  const nx = ndstate + nastate;\n  const ndiff = ndstate, nalg = nastate, nu = ninput, NP = 0;\n  const NXD = nicp * nk * (deg + 1) * ndiff;\n  const NXA = nicp * nk * deg * nalg;\n  const NU = nk * nu;\n  const NXF = ndiff;\n  const NV = NXD + NXA + NU + NXF + NP;\n\n  const V = M.MX.sym(\"V\", NV);\n  const Vrows = M.vertsplit(V, Array.from({ length: NV + 1 }, (_, i) => i));\n  const slice = (a, b) => M.vertcat.apply(null, Vrows.slice(a, b));\n\n  const vars_lb = new Array(NV).fill(0);\n  const vars_ub = new Array(NV).fill(0);\n  const vars_init = new Array(NV).fill(0);\n  const setRange = (arr, off, vals) => { for (let i = 0; i < vals.length; ++i) arr[off + i] = vals[i]; };\n\n  // XD[k][i][j], XA[k][i][j-1], U[k]\n  const XD = Array.from({ length: nk + 1 }, () => Array.from({ length: nicp }, () => new Array(deg + 1).fill(null)));\n  const XA = Array.from({ length: nk }, () => Array.from({ length: nicp }, () => new Array(deg).fill(null)));\n  const U = new Array(nk).fill(null);\n\n  let offset = 0;\n  for (let k = 0; k < nk; ++k) {\n    for (let i = 0; i < nicp; ++i) {\n      for (let j = 0; j <= deg; ++j) {\n        XD[k][i][j] = slice(offset, offset + ndiff);\n        if (j !== 0) XA[k][i][j - 1] = slice(offset + ndiff, offset + ndiff + nalg);\n        if (k === 0 && j === 0 && i === 0) {\n          setRange(vars_init, offset, xD_init);\n          setRange(vars_lb, offset, xDi_min);\n          setRange(vars_ub, offset, xDi_max);\n          offset += ndiff;\n        } else if (j !== 0) {\n          setRange(vars_init, offset, xD_init.concat(xA_init));\n          setRange(vars_lb, offset, xD_min.concat(xA_min));\n          setRange(vars_ub, offset, xD_max.concat(xA_max));\n          offset += nx;\n        } else {\n          setRange(vars_init, offset, xD_init);\n          setRange(vars_lb, offset, xD_min);\n          setRange(vars_ub, offset, xD_max);\n          offset += ndiff;\n        }\n      }\n    }\n    U[k] = slice(offset, offset + nu);\n    setRange(vars_lb, offset, u_min);\n    setRange(vars_ub, offset, u_max);\n    setRange(vars_init, offset, [0.0]);\n    offset += nu;\n  }\n  XD[nk][0][0] = slice(offset, offset + ndiff);\n  setRange(vars_lb, offset, xD_min);\n  setRange(vars_ub, offset, xD_max);\n  setRange(vars_init, offset, xD_init);\n  offset += ndiff;\n  if (offset !== NV) throw new Error(\"offset != NV (\" + offset + \" vs \" + NV + \")\");\n\n  const P = M.MX(0, 1);\n\n  // -------- Constraints --------\n  const gcon = [];\n  // Collocation + continuity equations\n  for (let k = 0; k < nk; ++k) {\n    for (let i = 0; i < nicp; ++i) {\n      for (let j = 1; j <= deg; ++j) {\n        let xp_jk = M.MX.zeros(ndiff);\n        for (let j2 = 0; j2 <= deg; ++j2) xp_jk = M.plus(xp_jk, M.times(C[j2][j], XD[k][i][j2]));\n        const fk = ffcn.call([M.DM(0), M.rdivide(xp_jk, h), XD[k][i][j], XA[k][i][j - 1], U[k], P])[0];\n        const fkrows = M.vertsplit(fk, [0, ndiff, ndiff + nalg]);\n        gcon.push(fkrows[0]); // differential part == 0\n        gcon.push(fkrows[1]); // algebraic part == 0\n      }\n      let xf_k = M.MX.zeros(ndiff);\n      for (let j = 0; j <= deg; ++j) xf_k = M.plus(xf_k, M.times(D[j], XD[k][i][j]));\n      if (i === nicp - 1) gcon.push(M.minus(XD[k + 1][0][0], xf_k));\n      else gcon.push(M.minus(XD[k][i + 1][0], xf_k));\n    }\n  }\n\n  // -------- Objective --------\n  // Mayer term at the final collocation node\n  let Obj = MayerTerm.call([M.DM(0), XD[nk - 1][0][deg], XA[nk - 1][0][deg - 1], U[nk - 1], P])[0];\n\n  // Lagrange term via the collocation quadrature weights\n  // lDotAtTauRoot = C.T ; ldInv = inv(C.T[1:,1:]) ; lAtOne = D\n  const CT = Array.from({ length: deg + 1 }, (_, a) => Array.from({ length: deg + 1 }, (_, b) => C[b][a]));\n  const ldInv = M.MX(M.inv(M.DM(CT.slice(1).map((row) => row.slice(1)))));\n  const lAtOne1 = M.MX(M.DM(D.slice(1)));\n\n  for (let k = 0; k < nk; ++k) {\n    for (let i = 0; i < nicp; ++i) {\n      const dqParts = [];\n      for (let j = 1; j <= deg; ++j) {\n        dqParts.push(LagrangeTerm.call([M.DM(0), XD[k][i][j], XA[k][i][j - 1], U[k], P])[0]);\n      }\n      const dQs = M.times(h, M.vertcat.apply(null, dqParts)); // deg x 1\n      const Qs = M.mtimes(ldInv, dQs);                       // deg x 1\n      Obj = M.plus(Obj, M.mtimes(M.transpose(Qs), lAtOne1)); // scalar\n    }\n  }\n  // -------- Solve --------\n  // NB: integer-valued ipopt sub-options (e.g. ipopt.max_iter) are mis-cast\n  // by the wasm option bridge and clamp the solve to 1 iteration, so we rely\n  // on the default max_iter here.\n  const nlp = { x: V, f: Obj, g: M.vertcat.apply(null, gcon) };\n  const solver = M.nlpsol(\"solver\", \"ipopt\", nlp,\n    { expand: true, \"ipopt.tol\": 1e-4, \"ipopt.print_level\": 0, print_time: false });\n\n  const sol = solver.call({\n    x0: M.DM(vars_init), lbx: M.DM(vars_lb), ubx: M.DM(vars_ub), lbg: M.DM(0), ubg: M.DM(0),\n  });\n\n  log(\"optimal cost: \" + sol[\"f\"].nonzeros()[0].toFixed(6));\n\n  // Sample the chariot position x (xd[0]) at the start of each finite element\n  const v_opt = sol[\"x\"].nonzeros();\n  log(\"chariot position x at element starts (every 10th):\");\n  let off = 0;\n  const xstarts = [];\n  for (let k = 0; k < nk; ++k) {\n    xstarts.push(v_opt[off]); // first state of first node in element\n    for (let i = 0; i < nicp; ++i) {\n      for (let j = 0; j <= deg; ++j) { off += ndiff; if (j !== 0) off += nalg; }\n    }\n    off += nu;\n  }\n  for (let k = 0; k < nk; k += 10) log(\"  k=\" + k + \"  x=\" + xstarts[k].toFixed(5));\n  log(\"final x = \" + v_opt[off].toFixed(5) + \" (target xref = \" + xref + \")\");\n}\n\nif (typeof require !== \"undefined\" && typeof module !== \"undefined\" && require.main === module) {\n  const path = require(\"path\");\n  const casadiPath = process.env.CASADI_JS\n    || path.resolve(__dirname, \"../../../build-wasm/swig/wasm-js/casadi.js\");\n  require(casadiPath)()\n    .then((M) => example(M, (...a) => console.log(...a)))\n    .catch((e) => { console.error(\"FATAL:\", e.message || e); process.exit(1); });\n}\n\nif (typeof module !== \"undefined\" && module.exports) module.exports = example;\n",
  "dae_multiple_shooting.js": "//\n//     MIT No Attribution\n//\n//     Copyright (C) 2010-2023 Joel Andersson, Joris Gillis, Moritz Diehl, KU Leuven.\n//\n//     Permission is hereby granted, free of charge, to any person obtaining a copy of this\n//     software and associated documentation files (the \"Software\"), to deal in the Software\n//     without restriction, including without limitation the rights to use, copy, modify,\n//     merge, publish, distribute, sublicense, and/or sell copies of the Software, and to\n//     permit persons to whom the Software is furnished to do so.\n//\n//     THE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED,\n//     INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A\n//     PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT\n//     HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION\n//     OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE\n//     SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.\n//\n//\n// JS port of docs/examples/python/dae_multiple_shooting.py.\n//\n// Direct multiple shooting on a DAE optimal control problem:\n//   min  int_0^10 (x0^2 + x1^2 + u^2) dt\n//   s.t. dot(x0) = z*x0 - x1 + u,  dot(x1) = x0,  0 = x1^2 + z - 1\n//        x0(0)=0, x1(0)=1, x0(10)=0, x1(10)=0,  -0.75 <= u <= 1\n// The Python version integrates with \"idas\"; that DAE integrator is not\n// linked in the wasm build, so this port SUBSTITUTES the \"collocation\"\n// integrator (which also supports algebraic states).\n//\n// JS notes (see README.md):\n//   * Python's `inf` becomes JS `Infinity`.\n//   * The integrator is called per shooting interval; xf/qf are read from\n//     the returned name-keyed dict.\n\nasync function example(M, log) {\n  // Declare variables\n  const x0 = M.SX.sym(\"x0\");\n  const x1 = M.SX.sym(\"x1\");\n  const x = M.vertcat(x0, x1); // differential states\n  const z = M.SX.sym(\"z\");     // algebraic variable\n  const u = M.SX.sym(\"u\");     // control\n\n  // Differential equation\n  const f_x = M.vertcat(M.plus(M.minus(M.times(z, x0), x1), u), x0);\n  // Algebraic equation\n  const f_z = M.minus(M.plus(M.power(x1, 2), z), 1);\n  // Lagrange cost term (quadrature)\n  const f_q = M.plus(M.plus(M.power(x0, 2), M.power(x1, 2)), M.power(u, 2));\n\n  // Create an integrator (collocation substituted for idas), interval 0.5s\n  const dae = { x: x, z: z, p: u, ode: f_x, alg: f_z, quad: f_q };\n  const I = M.integrator(\"I\", \"collocation\", dae, 0, 0.5);\n\n  // Number of intervals\n  const nk = 20;\n\n  // Build the NLP via direct multiple shooting\n  const w = [];   // variables\n  const lbw = [];\n  const ubw = [];\n  const G = [];   // constraints\n  let J = M.MX(0);\n\n  // Initial conditions\n  let Xk = M.MX.sym(\"X0\", 2);\n  w.push(Xk);\n  lbw.push(0, 1); ubw.push(0, 1);\n\n  for (let k = 0; k < nk; ++k) {\n    // Local control\n    const Uk = M.MX.sym(\"U\" + k);\n    w.push(Uk);\n    lbw.push(-0.75); ubw.push(1.0);\n\n    // Integrate over the interval\n    const Ik = I.call({ x0: Xk, p: Uk });\n    const X_prev = Ik[\"xf\"];\n    J = M.plus(J, Ik[\"qf\"]);\n\n    // Lift the state variable\n    Xk = M.MX.sym(\"X\" + (k + 1), 2);\n    w.push(Xk);\n    lbw.push(-Infinity, -Infinity); ubw.push(Infinity, Infinity);\n    G.push(M.minus(X_prev, Xk));\n  }\n\n  // Allocate an NLP solver\n  const nlp = { x: M.vertcat.apply(null, w), f: J, g: M.vertcat.apply(null, G) };\n  const solver = M.nlpsol(\"solver\", \"ipopt\", nlp,\n    { \"ipopt.print_level\": 0, print_time: false });\n\n  const sol = solver.call({\n    lbx: M.DM(lbw), ubx: M.DM(ubw), lbg: M.DM(0), ubg: M.DM(0), x0: M.DM(0),\n  });\n\n  log(\"optimal cost = \" + sol[\"f\"].nonzeros()[0].toFixed(6));\n\n  // Layout per interval: [x0, x1, u]; final block has [x0, x1].\n  const nz = sol[\"x\"].nonzeros();\n  log(\"interval samples (t, x0, x1, u):\");\n  for (let k = 0; k <= nk; k += 4) {\n    const t = (10.0 * k) / nk;\n    const xa = nz[3 * k], xb = nz[3 * k + 1];\n    const uu = k < nk ? nz[3 * k + 2].toFixed(4) : \"  -  \";\n    log(\"  t=\" + t.toFixed(2) + \"  x0=\" + xa.toFixed(4) + \"  x1=\" + xb.toFixed(4) + \"  u=\" + uu);\n  }\n}\n\nif (typeof require !== \"undefined\" && typeof module !== \"undefined\" && require.main === module) {\n  const path = require(\"path\");\n  const casadiPath = process.env.CASADI_JS\n    || path.resolve(__dirname, \"../../../build-wasm/swig/wasm-js/casadi.js\");\n  require(casadiPath)()\n    .then((M) => example(M, (...a) => console.log(...a)))\n    .catch((e) => { console.error(\"FATAL:\", e.message || e); process.exit(1); });\n}\n\nif (typeof module !== \"undefined\" && module.exports) module.exports = example;\n",
  "dae_single_shooting.js": "//\n//     MIT No Attribution\n//\n//     Copyright (C) 2010-2023 Joel Andersson, Joris Gillis, Moritz Diehl, KU Leuven.\n//\n//     Permission is hereby granted, free of charge, to any person obtaining a copy of this\n//     software and associated documentation files (the \"Software\"), to deal in the Software\n//     without restriction, including without limitation the rights to use, copy, modify,\n//     merge, publish, distribute, sublicense, and/or sell copies of the Software, and to\n//     permit persons to whom the Software is furnished to do so.\n//\n//     THE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED,\n//     INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A\n//     PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT\n//     HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION\n//     OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE\n//     SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.\n//\n//\n// JS port of docs/examples/python/dae_single_shooting.py.\n//\n// Direct single shooting on a small DAE OCP.\n//\n//   minimize   integral_{0}^{10} x0^2 + x1^2 + u^2 dt\n//   s.t.       dot(x0) == z*x0 - x1 + u\n//              dot(x1) == x0\n//                    0 == x1^2 + z - 1\n//              x0(0)=0, x1(0)=1, x0(10)=x1(10)=0,  -0.75 <= u <= 1\n//\n// JS notes (see README.md):\n//   * The Python version uses the \"idas\" DAE integrator, which aborts the\n//     wasm runtime. We substitute \"collocation\", which handles the implicit\n//     algebraic equation and produces an equivalent solution.\n//   * The Python `ma27` linear solver option is dropped (default mumps used).\n\nasync function example(M, log) {\n  // Declare variables\n  const x = M.SX.sym(\"x\", 2);   // Differential states\n  const z = M.SX.sym(\"z\");      // Algebraic variable\n  const u = M.SX.sym(\"u\");      // Control\n  const [x0e, x1e] = M.vertsplit(x);\n\n  // Differential equation\n  const f_x = M.vertcat(M.plus(M.minus(M.times(z, x0e), x1e), u), x0e);\n\n  // Algebraic equation\n  const f_z = M.minus(M.plus(M.times(x1e, x1e), z), 1);\n\n  // Lagrange cost term (quadrature)\n  const f_q = M.plus(M.plus(M.times(x0e, x0e), M.times(x1e, x1e)), M.times(u, u));\n\n  // Create an integrator (interval length 0.5s) -- \"collocation\" stands in for \"idas\"\n  const dae = { x: x, z: z, p: u, ode: f_x, alg: f_z, quad: f_q };\n  const I = M.integrator(\"I\", \"collocation\", dae, 0, 0.5);\n\n  // All controls\n  const U = M.MX.sym(\"U\", 20);\n  const Us = M.vertsplit(U);\n\n  // Construct graph of integrator calls\n  let X = M.MX([0, 1]);\n  let J = M.MX(0);\n  for (let k = 0; k < 20; k++) {\n    const Ik = I.call({ x0: X, p: Us[k] });\n    X = Ik[\"xf\"];\n    J = M.plus(J, Ik[\"qf\"]);   // Sum up quadratures\n  }\n\n  // Allocate an NLP solver\n  const nlp = { x: U, f: J, g: X };\n  const solver = M.nlpsol(\"solver\", \"ipopt\", nlp);\n\n  // Pass bounds, initial guess and solve NLP\n  const sol = solver.call({\n    lbx: -0.75,   // Lower variable bound\n    ubx: 1.0,     // Upper variable bound\n    lbg: 0.0,     // Lower constraint bound\n    ubg: 0.0,     // Upper constraint bound\n    x0: 0.0,      // Initial guess\n  });\n\n  log(\"-----\");\n  log(\"objective at solution = \" + sol[\"f\"].nonzeros().join(\" \"));\n  log(\"u_opt = \" + sol[\"x\"].nonzeros().map((v) => v.toFixed(4)).join(\" \"));\n  log(\"terminal state x(10) = \" + sol[\"g\"].nonzeros().map((v) => v.toExponential(2)).join(\" \"));\n}\n\nif (typeof require !== \"undefined\" && typeof module !== \"undefined\" && require.main === module) {\n  const path = require(\"path\");\n  const casadiPath = process.env.CASADI_JS\n    || path.resolve(__dirname, \"../../../build-wasm/swig/wasm-js/casadi.js\");\n  require(casadiPath)()\n    .then((M) => example(M, (...a) => console.log(...a)))\n    .catch((e) => { console.error(\"FATAL:\", e.message || e); process.exit(1); });\n}\n\nif (typeof module !== \"undefined\" && module.exports) module.exports = example;\n",
  "direct_collocation.js": "//\n//     MIT No Attribution\n//\n//     Copyright (C) 2010-2023 Joel Andersson, Joris Gillis, Moritz Diehl, KU Leuven.\n//\n//     Permission is hereby granted, free of charge, to any person obtaining a copy of this\n//     software and associated documentation files (the \"Software\"), to deal in the Software\n//     without restriction, including without limitation the rights to use, copy, modify,\n//     merge, publish, distribute, sublicense, and/or sell copies of the Software, and to\n//     permit persons to whom the Software is furnished to do so.\n//\n//     THE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED,\n//     INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A\n//     PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT\n//     HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION\n//     OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE\n//     SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.\n//\n//\n// JS port of docs/examples/python/direct_collocation.py.\n//\n// Direct collocation transcription of a Van der Pol OCP, building the\n// collocation coefficients by hand (no integrator plugin) -> fully portable.\n//\n// JS notes (see README.md):\n//   * numpy poly1d/polyder/polyint are replaced by small array-based helpers.\n//   * ca.collocation_points(d, ...) returns a plain JS number[] here.\n//   * matplotlib output is dropped; we log the optimum instead.\n\n// Polynomial helpers (coeffs highest-degree-first, like numpy.poly1d).\nfunction polymul(a, b) {\n  const r = new Array(a.length + b.length - 1).fill(0);\n  for (let i = 0; i < a.length; i++)\n    for (let j = 0; j < b.length; j++) r[i + j] += a[i] * b[j];\n  return r;\n}\nfunction polyval(p, x) { let r = 0; for (const c of p) r = r * x + c; return r; }\nfunction polyder(p) {\n  const n = p.length - 1, r = [];\n  for (let i = 0; i < n; i++) r.push(p[i] * (n - i));\n  return r.length ? r : [0];\n}\nfunction polyint(p) {\n  const n = p.length, r = [];\n  for (let i = 0; i < n; i++) r.push(p[i] / (n - i));\n  r.push(0);\n  return r;\n}\n\nasync function example(M, log) {\n  // Degree of interpolating polynomial\n  const d = 3;\n\n  // Collocation points (prepend 0)\n  const tau_root = [0, ...M.collocation_points(d, \"legendre\")];\n\n  // Coefficients of the collocation, continuity and quadrature equations\n  const C = Array.from({ length: d + 1 }, () => new Array(d + 1).fill(0));\n  const D = new Array(d + 1).fill(0);\n  const B = new Array(d + 1).fill(0);\n\n  // Construct polynomial basis\n  for (let j = 0; j <= d; j++) {\n    let p = [1];\n    for (let r = 0; r <= d; r++)\n      if (r !== j) p = polymul(p, [1, -tau_root[r]]).map((c) => c / (tau_root[j] - tau_root[r]));\n    // Continuity coefficient\n    D[j] = polyval(p, 1.0);\n    // Collocation coefficients\n    const pder = polyder(p);\n    for (let r = 0; r <= d; r++) C[j][r] = polyval(pder, tau_root[r]);\n    // Quadrature coefficient\n    B[j] = polyval(polyint(p), 1.0);\n  }\n\n  // Time horizon\n  const T = 10.0;\n\n  // Declare model variables\n  const x1 = M.SX.sym(\"x1\");\n  const x2 = M.SX.sym(\"x2\");\n  const x = M.vertcat(x1, x2);\n  const u = M.SX.sym(\"u\");\n\n  // Model equations\n  const xdot = M.vertcat(\n    M.plus(M.minus(M.times(M.minus(1, M.times(x2, x2)), x1), x2), u),\n    x1);\n\n  // Objective term\n  const L = M.plus(M.plus(M.times(x1, x1), M.times(x2, x2)), M.times(u, u));\n\n  // Continuous time dynamics\n  const f = new M.Function(\"f\", [x, u], [xdot, L], [\"x\", \"u\"], [\"xdot\", \"L\"]);\n\n  // Control discretization\n  const N = 20;       // number of control intervals\n  const h = T / N;\n\n  // Start with an empty NLP\n  const w = [], w0 = [], lbw = [], ubw = [];\n  let J = M.MX(0);\n  const g = [], lbg = [], ubg = [];\n\n  // For plotting/logging x and u given w\n  const x_plot = [], u_plot = [];\n\n  // \"Lift\" initial conditions\n  let Xk = M.MX.sym(\"X0\", 2);\n  w.push(Xk); lbw.push(0, 1); ubw.push(0, 1); w0.push(0, 1); x_plot.push(Xk);\n\n  // Formulate the NLP\n  for (let k = 0; k < N; k++) {\n    // New NLP variable for the control\n    const Uk = M.MX.sym(\"U_\" + k);\n    w.push(Uk); lbw.push(-1); ubw.push(1); w0.push(0); u_plot.push(Uk);\n\n    // State at collocation points\n    const Xc = [];\n    for (let j = 0; j < d; j++) {\n      const Xkj = M.MX.sym(\"X_\" + k + \"_\" + j, 2);\n      Xc.push(Xkj); w.push(Xkj);\n      lbw.push(-0.25, -Infinity); ubw.push(Infinity, Infinity); w0.push(0, 0);\n    }\n\n    // Loop over collocation points\n    let Xk_end = M.times(D[0], Xk);\n    for (let j = 1; j <= d; j++) {\n      // Expression for the state derivative at the collocation point\n      let xp = M.times(C[0][j], Xk);\n      for (let r = 0; r < d; r++) xp = M.plus(xp, M.times(C[r + 1][j], Xc[r]));\n\n      // Append collocation equations\n      const fj = f.call([Xc[j - 1], Uk]);\n      g.push(M.minus(M.times(h, fj[0]), xp)); lbg.push(0, 0); ubg.push(0, 0);\n\n      // Add contribution to the end state\n      Xk_end = M.plus(Xk_end, M.times(D[j], Xc[j - 1]));\n\n      // Add contribution to quadrature function\n      J = M.plus(J, M.times(B[j], M.times(fj[1], h)));\n    }\n\n    // New NLP variable for state at end of interval\n    Xk = M.MX.sym(\"X_\" + (k + 1), 2);\n    w.push(Xk); lbw.push(-0.25, -Infinity); ubw.push(Infinity, Infinity); w0.push(0, 0);\n    x_plot.push(Xk);\n\n    // Add equality constraint\n    g.push(M.minus(Xk_end, Xk)); lbg.push(0, 0); ubg.push(0, 0);\n  }\n\n  // Concatenate vectors\n  const W = M.vcat(w);\n  const G = M.vcat(g);\n  const x_plot_m = M.hcat(x_plot);\n  const u_plot_m = M.hcat(u_plot);\n\n  // Create an NLP solver\n  const prob = { f: J, x: W, g: G };\n  const solver = M.nlpsol(\"solver\", \"ipopt\", prob);\n\n  // Function to get x and u trajectories from w\n  const trajectories = new M.Function(\"trajectories\", [W], [x_plot_m, u_plot_m], [\"w\"], [\"x\", \"u\"]);\n\n  // Solve the NLP\n  const sol = solver.call({\n    x0: M.DM(w0), lbx: M.DM(lbw), ubx: M.DM(ubw), lbg: M.DM(lbg), ubg: M.DM(ubg),\n  });\n  const [x_opt, u_opt] = trajectories.call([sol[\"x\"]]);\n\n  // Report the solution\n  log(\"-----\");\n  log(\"objective at solution = \" + sol[\"f\"].nonzeros().join(\" \"));\n  log(\"x1 trajectory = \" + x_opt.nonzeros().filter((_, i) => i % 2 === 0).map((v) => v.toFixed(4)).join(\" \"));\n  log(\"x2 trajectory = \" + x_opt.nonzeros().filter((_, i) => i % 2 === 1).map((v) => v.toFixed(4)).join(\" \"));\n  log(\"u trajectory = \" + u_opt.nonzeros().map((v) => v.toFixed(4)).join(\" \"));\n}\n\nif (typeof require !== \"undefined\" && typeof module !== \"undefined\" && require.main === module) {\n  const path = require(\"path\");\n  const casadiPath = process.env.CASADI_JS\n    || path.resolve(__dirname, \"../../../build-wasm/swig/wasm-js/casadi.js\");\n  require(casadiPath)()\n    .then((M) => example(M, (...a) => console.log(...a)))\n    .catch((e) => { console.error(\"FATAL:\", e.message || e); process.exit(1); });\n}\n\nif (typeof module !== \"undefined\" && module.exports) module.exports = example;\n",
  "direct_multiple_shooting.js": "//\n//     MIT No Attribution\n//\n//     Copyright (C) 2010-2023 Joel Andersson, Joris Gillis, Moritz Diehl, KU Leuven.\n//\n//     Permission is hereby granted, free of charge, to any person obtaining a copy of this\n//     software and associated documentation files (the \"Software\"), to deal in the Software\n//     without restriction, including without limitation the rights to use, copy, modify,\n//     merge, publish, distribute, sublicense, and/or sell copies of the Software, and to\n//     permit persons to whom the Software is furnished to do so.\n//\n//     THE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED,\n//     INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A\n//     PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT\n//     HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION\n//     OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE\n//     SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.\n//\n//\n// JS port of docs/examples/python/direct_multiple_shooting.py.\n//\n// Direct multiple shooting on a Van der Pol OCP. The Python version offers a\n// CVODES branch (disabled by `if False`); we keep the fixed-step RK4 branch,\n// which is the active one and fully portable.\n//\n// JS notes (see README.md): matplotlib output is dropped; key numbers logged.\n\nasync function example(M, log) {\n  const T = 10.0;  // Time horizon\n  const N = 20;    // number of control intervals\n\n  // Declare model variables\n  const x1 = M.MX.sym(\"x1\");\n  const x2 = M.MX.sym(\"x2\");\n  const x = M.vertcat(x1, x2);\n  const u = M.MX.sym(\"u\");\n\n  // Model equations\n  const xdot = M.vertcat(\n    M.plus(M.minus(M.times(M.minus(1, M.times(x2, x2)), x1), x2), u),\n    x1);\n\n  // Objective term\n  const L = M.plus(M.plus(M.times(x1, x1), M.times(x2, x2)), M.times(u, u));\n\n  // Formulate discrete time dynamics: fixed step Runge-Kutta 4 integrator\n  const Msteps = 4;            // RK4 steps per interval\n  const DT = T / N / Msteps;\n  const f = new M.Function(\"f\", [x, u], [xdot, L]);\n  const X0 = M.MX.sym(\"X0\", 2);\n  const U = M.MX.sym(\"U\");\n  let X = X0;\n  let Q = M.MX(0);\n  for (let j = 0; j < Msteps; j++) {\n    const [k1, k1q] = f.call([X, U]);\n    const [k2, k2q] = f.call([M.plus(X, M.times(DT / 2, k1)), U]);\n    const [k3, k3q] = f.call([M.plus(X, M.times(DT / 2, k2)), U]);\n    const [k4, k4q] = f.call([M.plus(X, M.times(DT, k3)), U]);\n    X = M.plus(X, M.times(DT / 6, M.plus(M.plus(k1, M.times(2, k2)), M.plus(M.times(2, k3), k4))));\n    Q = M.plus(Q, M.times(DT / 6, M.plus(M.plus(k1q, M.times(2, k2q)), M.plus(M.times(2, k3q), k4q))));\n  }\n  const F = new M.Function(\"F\", [X0, U], [X, Q], [\"x0\", \"p\"], [\"xf\", \"qf\"]);\n\n  // Evaluate at a test point\n  const Fk0 = F.call({ x0: M.DM([0.2, 0.3]), p: M.DM(0.4) });\n  log(\"test xf = \" + Fk0[\"xf\"].nonzeros().join(\" \"));\n  log(\"test qf = \" + Fk0[\"qf\"].nonzeros().join(\" \"));\n\n  // Start with an empty NLP\n  const w = [], w0 = [], lbw = [], ubw = [];\n  let J = M.MX(0);\n  const g = [], lbg = [], ubg = [];\n\n  // \"Lift\" initial conditions\n  let Xk = M.MX.sym(\"X0\", 2);\n  w.push(Xk); lbw.push(0, 1); ubw.push(0, 1); w0.push(0, 1);\n\n  // Formulate the NLP\n  for (let k = 0; k < N; k++) {\n    // New NLP variable for the control\n    const Uk = M.MX.sym(\"U_\" + k);\n    w.push(Uk); lbw.push(-1); ubw.push(1); w0.push(0);\n\n    // Integrate till the end of the interval\n    const Fk = F.call({ x0: Xk, p: Uk });\n    const Xk_end = Fk[\"xf\"];\n    J = M.plus(J, Fk[\"qf\"]);\n\n    // New NLP variable for state at end of interval\n    Xk = M.MX.sym(\"X_\" + (k + 1), 2);\n    w.push(Xk); lbw.push(-0.25, -Infinity); ubw.push(Infinity, Infinity); w0.push(0, 0);\n\n    // Add equality constraint\n    g.push(M.minus(Xk_end, Xk)); lbg.push(0, 0); ubg.push(0, 0);\n  }\n\n  // Create an NLP solver\n  const prob = { f: J, x: M.vcat(w), g: M.vcat(g) };\n  const solver = M.nlpsol(\"solver\", \"ipopt\", prob);\n\n  // Solve the NLP\n  const sol = solver.call({\n    x0: M.DM(w0), lbx: M.DM(lbw), ubx: M.DM(ubw), lbg: M.DM(lbg), ubg: M.DM(ubg),\n  });\n  const w_opt = sol[\"x\"].nonzeros();\n\n  // Plot the solution: layout is [x1, x2, u] repeating\n  const x1_opt = w_opt.filter((_, i) => i % 3 === 0);\n  const x2_opt = w_opt.filter((_, i) => i % 3 === 1);\n  const u_opt = w_opt.filter((_, i) => i % 3 === 2);\n\n  log(\"-----\");\n  log(\"objective at solution = \" + sol[\"f\"].nonzeros().join(\" \"));\n  log(\"x1_opt = \" + x1_opt.map((v) => v.toFixed(4)).join(\" \"));\n  log(\"x2_opt = \" + x2_opt.map((v) => v.toFixed(4)).join(\" \"));\n  log(\"u_opt = \" + u_opt.map((v) => v.toFixed(4)).join(\" \"));\n}\n\nif (typeof require !== \"undefined\" && typeof module !== \"undefined\" && require.main === module) {\n  const path = require(\"path\");\n  const casadiPath = process.env.CASADI_JS\n    || path.resolve(__dirname, \"../../../build-wasm/swig/wasm-js/casadi.js\");\n  require(casadiPath)()\n    .then((M) => example(M, (...a) => console.log(...a)))\n    .catch((e) => { console.error(\"FATAL:\", e.message || e); process.exit(1); });\n}\n\nif (typeof module !== \"undefined\" && module.exports) module.exports = example;\n",
  "direct_single_shooting.js": "//\n//     MIT No Attribution\n//\n//     Copyright (C) 2010-2023 Joel Andersson, Joris Gillis, Moritz Diehl, KU Leuven.\n//\n//     Permission is hereby granted, free of charge, to any person obtaining a copy of this\n//     software and associated documentation files (the \"Software\"), to deal in the Software\n//     without restriction, including without limitation the rights to use, copy, modify,\n//     merge, publish, distribute, sublicense, and/or sell copies of the Software, and to\n//     permit persons to whom the Software is furnished to do so.\n//\n//     THE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED,\n//     INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A\n//     PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT\n//     HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION\n//     OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE\n//     SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.\n//\n//\n// JS port of docs/examples/python/direct_single_shooting.py.\n//\n// Direct single shooting on a Van der Pol OCP. The Python version offers a\n// CVODES branch (disabled by `if False`); we keep the fixed-step RK4 branch,\n// which is the active one and fully portable.\n//\n// JS notes (see README.md): matplotlib output is dropped; key numbers logged.\n\nasync function example(M, log) {\n  const T = 10.0;  // Time horizon\n  const N = 20;    // number of control intervals\n\n  // Declare model variables\n  const x1 = M.MX.sym(\"x1\");\n  const x2 = M.MX.sym(\"x2\");\n  const x = M.vertcat(x1, x2);\n  const u = M.MX.sym(\"u\");\n\n  // Model equations\n  const xdot = M.vertcat(\n    M.plus(M.minus(M.times(M.minus(1, M.times(x2, x2)), x1), x2), u),\n    x1);\n\n  // Objective term\n  const L = M.plus(M.plus(M.times(x1, x1), M.times(x2, x2)), M.times(u, u));\n\n  // Formulate discrete time dynamics: fixed step Runge-Kutta 4 integrator\n  const Msteps = 4;            // RK4 steps per interval\n  const DT = T / N / Msteps;\n  const f = new M.Function(\"f\", [x, u], [xdot, L]);\n  const X0 = M.MX.sym(\"X0\", 2);\n  const U = M.MX.sym(\"U\");\n  let X = X0;\n  let Q = M.MX(0);\n  for (let j = 0; j < Msteps; j++) {\n    const [k1, k1q] = f.call([X, U]);\n    const [k2, k2q] = f.call([M.plus(X, M.times(DT / 2, k1)), U]);\n    const [k3, k3q] = f.call([M.plus(X, M.times(DT / 2, k2)), U]);\n    const [k4, k4q] = f.call([M.plus(X, M.times(DT, k3)), U]);\n    X = M.plus(X, M.times(DT / 6, M.plus(M.plus(k1, M.times(2, k2)), M.plus(M.times(2, k3), k4))));\n    Q = M.plus(Q, M.times(DT / 6, M.plus(M.plus(k1q, M.times(2, k2q)), M.plus(M.times(2, k3q), k4q))));\n  }\n  const F = new M.Function(\"F\", [X0, U], [X, Q], [\"x0\", \"p\"], [\"xf\", \"qf\"]);\n\n  // Evaluate at a test point\n  const Fk0 = F.call({ x0: M.DM([0.2, 0.3]), p: M.DM(0.4) });\n  log(\"test xf = \" + Fk0[\"xf\"].nonzeros().join(\" \"));\n  log(\"test qf = \" + Fk0[\"qf\"].nonzeros().join(\" \"));\n\n  // Start with an empty NLP\n  const w = [], w0 = [], lbw = [], ubw = [];\n  let J = M.MX(0);\n  const g = [], lbg = [], ubg = [];\n\n  // Formulate the NLP\n  let Xk = M.MX([0, 1]);\n  for (let k = 0; k < N; k++) {\n    // New NLP variable for the control\n    const Uk = M.MX.sym(\"U_\" + k);\n    w.push(Uk); lbw.push(-1); ubw.push(1); w0.push(0);\n\n    // Integrate till the end of the interval\n    const Fk = F.call({ x0: Xk, p: Uk });\n    Xk = Fk[\"xf\"];\n    J = M.plus(J, Fk[\"qf\"]);\n\n    // Add inequality constraint\n    const [Xk0] = M.vertsplit(Xk);\n    g.push(Xk0); lbg.push(-0.25); ubg.push(Infinity);\n  }\n\n  // Create an NLP solver\n  const prob = { f: J, x: M.vcat(w), g: M.vcat(g) };\n  const solver = M.nlpsol(\"solver\", \"ipopt\", prob);\n\n  // Solve the NLP\n  const sol = solver.call({\n    x0: M.DM(w0), lbx: M.DM(lbw), ubx: M.DM(ubw), lbg: M.DM(lbg), ubg: M.DM(ubg),\n  });\n  const u_opt = sol[\"x\"].nonzeros();\n\n  // Re-simulate to recover the state trajectory\n  let xk = [0, 1];\n  const x1_opt = [xk[0]], x2_opt = [xk[1]];\n  for (let k = 0; k < N; k++) {\n    const Fk = F.call({ x0: M.DM(xk), p: M.DM(u_opt[k]) });\n    xk = Fk[\"xf\"].nonzeros();\n    x1_opt.push(xk[0]); x2_opt.push(xk[1]);\n  }\n\n  log(\"-----\");\n  log(\"objective at solution = \" + sol[\"f\"].nonzeros().join(\" \"));\n  log(\"u_opt = \" + u_opt.map((v) => v.toFixed(4)).join(\" \"));\n  log(\"x1_opt = \" + x1_opt.map((v) => v.toFixed(4)).join(\" \"));\n  log(\"x2_opt = \" + x2_opt.map((v) => v.toFixed(4)).join(\" \"));\n}\n\nif (typeof require !== \"undefined\" && typeof module !== \"undefined\" && require.main === module) {\n  const path = require(\"path\");\n  const casadiPath = process.env.CASADI_JS\n    || path.resolve(__dirname, \"../../../build-wasm/swig/wasm-js/casadi.js\");\n  require(casadiPath)()\n    .then((M) => example(M, (...a) => console.log(...a)))\n    .catch((e) => { console.error(\"FATAL:\", e.message || e); process.exit(1); });\n}\n\nif (typeof module !== \"undefined\" && module.exports) module.exports = example;\n",
  "implicit_runge-kutta.js": "//\n//     MIT No Attribution\n//\n//     Copyright (C) 2010-2023 Joel Andersson, Joris Gillis, Moritz Diehl, KU Leuven.\n//\n//     Permission is hereby granted, free of charge, to any person obtaining a copy of this\n//     software and associated documentation files (the \"Software\"), to deal in the Software\n//     without restriction, including without limitation the rights to use, copy, modify,\n//     merge, publish, distribute, sublicense, and/or sell copies of the Software, and to\n//     permit persons to whom the Software is furnished to do so.\n//\n//     THE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED,\n//     INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A\n//     PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT\n//     HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION\n//     OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE\n//     SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.\n//\n//\n// JS port of docs/examples/python/implicit_runge-kutta.py.\n//\n// Build a fixed-step implicit Runge-Kutta integrator by hand: a collocation\n// system solved with a rootfinder, iterated over finite elements, then\n// forward/adjoint directional derivatives via Function.factory.\n//\n// JS notes (see README.md):\n//   * The Python example also builds a 'cvodes' reference integrator and runs\n//     the same sensitivity checks on it.  cvodes is not in the wasm build, so\n//     we keep only the hand-built IRK integrator.\n//   * The rootfinder uses 'newton' (kinsol is not available in wasm).\n\nasync function example(M, log) {\n  // End time\n  const tf = 10.0;\n\n  // Dimensions\n  const nx = 3;\n  const np = 1;\n\n  // Declare variables\n  const x = M.SX.sym(\"x\", nx);  // state\n  const p = M.SX.sym(\"u\", np);  // control\n  const [xa, xb] = M.vertsplit(x); // x[0], x[1]\n\n  // ODE right hand side\n  const ode = M.vertcat(\n    M.plus(M.minus(M.times(M.minus(1, M.times(xb, xb)), xa), xb), p),\n    xa,\n    M.plus(M.plus(M.times(xa, xa), M.times(xb, xb)), M.times(p, p)));\n  const f = new M.Function(\"f\", [x, p], [ode]);\n\n  // Number of finite elements\n  const n = 100;\n  // Size of the finite elements\n  const h = tf / n;\n  // Degree of interpolating polynomial\n  const d = 4;\n\n  // Collocation points\n  const tau_root = [0, ...M.collocation_points(d, \"legendre\")];\n\n  // Coefficients of the collocation (C) and continuity (D) equations\n  const C = Array.from({ length: d + 1 }, () => new Array(d + 1).fill(0));\n  const D = new Array(d + 1).fill(0);\n\n  // Dimensionless time inside one control interval\n  const tau = M.SX.sym(\"tau\");\n\n  for (let j = 0; j <= d; j++) {\n    // Lagrange polynomial basis at collocation point j\n    let Lp = M.SX(1);\n    for (let r = 0; r <= d; r++)\n      if (r !== j) Lp = M.times(Lp, M.times(M.minus(tau, tau_root[r]), 1 / (tau_root[j] - tau_root[r])));\n    // Continuity coefficient\n    const lfcn = new M.Function(\"lfcn\", [tau], [Lp]);\n    D[j] = lfcn.call([M.DM(1.0)])[0].nonzeros()[0];\n    // Collocation coefficients\n    const tfcn = new M.Function(\"tfcn\", [tau], [M.tangent(Lp, tau)]);\n    for (let r = 0; r <= d; r++) C[j][r] = tfcn.call([M.DM(tau_root[r])])[0].nonzeros()[0];\n  }\n\n  // Variables for one finite element\n  const X0 = M.MX.sym(\"X0\", nx);\n  const Pm = M.MX.sym(\"P\", np);\n  const V = M.MX.sym(\"V\", d * nx);\n\n  // State at each collocation point: [X0, V split into d blocks of nx]\n  const offs = [];\n  for (let r = 0; r <= d; r++) offs.push(r * nx);\n  let X = [X0, ...M.vertsplit(V, offs)];\n\n  // Collocation equations defining V\n  const V_eq = [];\n  for (let j = 1; j <= d; j++) {\n    let xp_j = M.times(C[0][j], X[0]);\n    for (let r = 1; r <= d; r++) xp_j = M.plus(xp_j, M.times(C[r][j], X[r]));\n    const f_j = f.call([X[j], Pm])[0];\n    V_eq.push(M.minus(M.times(h, f_j), xp_j));\n  }\n  const V_eq_cat = M.vcat(V_eq);\n\n  // Root-finding function, implicitly defines V as a function of X0 and P\n  const vfcn = new M.Function(\"vfcn\", [V, X0, Pm], [V_eq_cat]);\n  const vfcn_sx = vfcn.expand();  // convert to SX to decrease overhead\n\n  // Implicit function instance (newton, not kinsol)\n  const ifcn = M.rootfinder(\"ifcn\", \"newton\", vfcn_sx);\n  const Vsol = ifcn.call([new M.MX(), X0, Pm])[0];\n\n  // Recover states and form end-of-element state\n  const Vparts = M.vertsplit(Vsol, offs);\n  X = [X0, ...Vparts];\n  let XF = M.times(D[0], X[0]);\n  for (let r = 1; r <= d; r++) XF = M.plus(XF, M.times(D[r], X[r]));\n\n  // Discrete time dynamics for one finite element\n  const F = new M.Function(\"F\", [X0, Pm], [XF]);\n\n  // Iterate over all finite elements\n  let Xacc = X0;\n  for (let i = 0; i < n; i++) Xacc = F.call([Xacc, Pm])[0];\n\n  // Fixed-step integrator (as a plain Function over x0, p -> xf)\n  const irk = new M.Function(\"irk_integrator\", [X0, Pm], [Xacc], [\"x0\", \"p\"], [\"xf\"]);\n\n  // Test values\n  const x0_val = M.DM([0, 1, 0]);\n  const p_val = M.DM(0.2);\n\n  log(\"-------\");\n  log(\"Testing \" + irk.name());\n  log(\"-------\");\n\n  // Forward and reverse directional derivatives\n  const dF = irk.factory(\"dF\",\n    [\"x0\", \"p\", \"fwd:x0\", \"fwd:p\", \"adj:xf\"],\n    [\"xf\", \"fwd:xf\", \"adj:x0\", \"adj:p\"]);\n\n  const res = dF.call({\n    x0: x0_val, p: p_val,\n    fwd_x0: M.DM([1, 0, 0]), fwd_p: M.DM(1),\n    adj_xf: M.DM([0, 0, 1]),\n  });\n\n  log(\"xf = \" + res[\"xf\"].nonzeros().map((v) => v.toFixed(6)).join(\" \"));\n  log(\"d(xf)/d(p)+d(xf)/d(x0[0]) = \" + res[\"fwd_xf\"].nonzeros().map((v) => v.toFixed(6)).join(\" \"));\n  log(\"d(xf[2])/d(x0) = \" + res[\"adj_x0\"].nonzeros().map((v) => v.toFixed(6)).join(\" \"));\n  log(\"d(xf[2])/d(p) = \" + res[\"adj_p\"].nonzeros().map((v) => v.toFixed(6)).join(\" \"));\n}\n\nif (typeof require !== \"undefined\" && typeof module !== \"undefined\" && require.main === module) {\n  const path = require(\"path\");\n  const casadiPath = process.env.CASADI_JS\n    || path.resolve(__dirname, \"../../../build-wasm/swig/wasm-js/casadi.js\");\n  require(casadiPath)()\n    .then((M) => example(M, (...a) => console.log(...a)))\n    .catch((e) => { console.error(\"FATAL:\", e.message || e); process.exit(1); });\n}\n\nif (typeof module !== \"undefined\" && module.exports) module.exports = example;\n",
  "lgl_pseudospectral_opti.js": "// Legendre-Gauss-Lobatto pseudospectral optimal-control example.\n// The initial guess for U uses scalar DM values because the browser SWIG\n// binding does not convert spread JavaScript numbers to DM automatically.\n\nfunction legendreAll(N, x) {\n  const length = x.length;\n  let P0 = new Array(length).fill(1);\n  let P1 = x.slice();\n  let dP0 = new Array(length).fill(0);\n  let dP1 = new Array(length).fill(1);\n  let d2P0 = new Array(length).fill(0);\n  let d2P1 = new Array(length).fill(0);\n  if (N === 0) return [P0, dP0, d2P0];\n  if (N === 1) return [P1, dP1, d2P1];\n\n  for (let k = 1; k < N; k++) {\n    const P2 = new Array(length);\n    const dP2 = new Array(length);\n    const d2P2 = new Array(length);\n    for (let i = 0; i < length; i++) {\n      P2[i] = ((2 * k + 1) * x[i] * P1[i] - k * P0[i]) / (k + 1);\n      dP2[i] = ((2 * k + 1) * (P1[i] + x[i] * dP1[i]) - k * dP0[i]) / (k + 1);\n      d2P2[i] = ((2 * k + 1) * (2 * dP1[i] + x[i] * d2P1[i]) - k * d2P0[i]) / (k + 1);\n    }\n    P0 = P1; P1 = P2; dP0 = dP1; dP1 = dP2; d2P0 = d2P1; d2P1 = d2P2;\n  }\n  return [P1, dP1, d2P1];\n}\n\nfunction lglNodes(N) {\n  if (N < 1) throw new Error(\"Degree N must be at least 1.\");\n  const nodes = Array.from({ length: N + 1 }, (_, k) => -Math.cos((Math.PI * k) / N));\n  nodes[0] = -1; nodes[N] = 1;\n  if (N > 1) {\n    const interior = nodes.slice(1, N);\n    for (let iteration = 0; iteration < 100; iteration++) {\n      const [, dP, d2P] = legendreAll(N, interior);\n      let largestStep = 0;\n      for (let i = 0; i < interior.length; i++) {\n        const step = dP[i] / d2P[i];\n        interior[i] -= step;\n        largestStep = Math.max(largestStep, Math.abs(step));\n      }\n      if (largestStep < 1e-15) break;\n    }\n    interior.forEach((value, index) => { nodes[index + 1] = value; });\n  }\n  for (let i = 0; i <= N; i++) nodes[i] = 0.5 * (nodes[i] - nodes[N - i]);\n  return nodes;\n}\n\nfunction lglWeights(N) {\n  const nodes = lglNodes(N);\n  const [PN] = legendreAll(N, nodes);\n  return PN.map((value, index) => {\n    const weight = 2 / (N * (N + 1) * value * value);\n    return 0.5 * (weight + 2 / (N * (N + 1) * PN[N - index] * PN[N - index]));\n  });\n}\n\nfunction lglDiffMatrix(N) {\n  const nodes = lglNodes(N);\n  const [PN] = legendreAll(N, nodes);\n  const matrix = Array.from({ length: N + 1 }, () => new Array(N + 1).fill(0));\n  for (let i = 0; i <= N; i++) {\n    for (let j = 0; j <= N; j++) {\n      if (i !== j) matrix[i][j] = (PN[i] / PN[j]) / (nodes[i] - nodes[j]);\n    }\n    matrix[i][i] = -matrix[i].reduce((sum, value) => sum + value, 0);\n  }\n  return matrix;\n}\n\nasync function example(M, log) {\n  const N = 25;\n  const t0 = 0;\n  const tf = 2;\n  const nx = 2;\n  const nu = 1;\n  const opti = new M.Opti();\n  const X = opti.variable(nx, N + 1);\n  const U = opti.variable(nu, N + 1);\n  const Xc = M.horzsplit(X);\n  const Uc = M.horzsplit(U);\n  const tau = lglNodes(N);\n  const weights = lglWeights(N);\n  const D = lglDiffMatrix(N);\n  const columns = D.map((row) => M.vertcat(...row.map((value) => M.DM(value))));\n  const differentiation = M.MX(M.horzcat(...columns));\n  const initialState = M.vertcat(0, 1);\n  const dynamics = M.horzcat(...Xc.map((state, index) => {\n    const [, speed] = M.vertsplit(state);\n    return M.vertcat(M.power(speed, 3), Uc[index]);\n  }));\n\n  opti.subject_to(M.eq(M.minus(M.mtimes(X, differentiation), M.times((tf - t0) / 2, dynamics)), 0));\n  opti.subject_to(M.eq(Xc[0], initialState));\n  const [finalPosition, finalSpeed] = M.vertsplit(Xc[N]);\n  const mayer = M.plus(M.times(4, finalPosition), finalSpeed);\n  const runningCost = weights.reduce((sum, weight, index) => M.plus(sum, M.times(weight, M.times(4, M.power(Uc[index], 2)))), M.MX(0));\n  opti.minimize(M.plus(mayer, M.times((tf - t0) / 2, runningCost)));\n\n  const initialColumns = Array.from({ length: N + 1 }, (_, index) => M.DM([index / N, index / N]));\n  opti.set_initial(X, M.horzcat(...initialColumns));\n  opti.set_initial(U, M.horzcat(...new Array(N + 1).fill(1).map((value) => M.DM(value))));\n  opti.solver(\"ipopt\");\n  const solution = opti.solve();\n  const XValue = solution.value(X);\n  const UValue = solution.value(U);\n  const [x1, x2] = M.vertsplit(XValue);\n  const times = tau.map((node) => ((tf - t0) / 2) * node + 0.5 * (tf + t0));\n\n  log(\"-----\");\n  log(\"LGL Pseudospectral OCP solved successfully\");\n  log(\"ts = \" + times.map((value) => value.toFixed(4)).join(\" \"));\n  log(\"x1 = \" + x1.nonzeros().map((value) => value.toFixed(4)).join(\" \"));\n  log(\"x2 = \" + x2.nonzeros().map((value) => value.toFixed(4)).join(\" \"));\n  log(\"u = \" + UValue.nonzeros().map((value) => value.toFixed(4)).join(\" \"));\n}\n",
  "multipoint_simulation.js": "//\n//     MIT No Attribution\n//\n//     Copyright (C) 2010-2023 Joel Andersson, Joris Gillis, Moritz Diehl, KU Leuven.\n//\n//     Permission is hereby granted, free of charge, to any person obtaining a copy of this\n//     software and associated documentation files (the \"Software\"), to deal in the Software\n//     without restriction, including without limitation the rights to use, copy, modify,\n//     merge, publish, distribute, sublicense, and/or sell copies of the Software, and to\n//     permit persons to whom the Software is furnished to do so.\n//\n//     THE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED,\n//     INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A\n//     PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT\n//     HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION\n//     OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE\n//     SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.\n//\n//\n// JS port of docs/examples/python/multipoint_simulation.py.\n//\n// Simulate a Van der Pol ODE over a grid, accumulating the integral of\n// the sum-of-squares output via the integrator's quadrature.\n//\n// JS notes (see README.md):\n//   * cvodes is not available in the wasm build; we substitute the \"rk\"\n//     (fixed-step Runge-Kutta) integrator, which handles this ODE fine.\n//   * numpy/matplotlib output is dropped; we log the trajectories.\n\nasync function example(M, log) {\n  // Nonlinear system with two states and one control input\n  const x1 = M.MX.sym(\"x1\");\n  const x2 = M.MX.sym(\"x2\");\n  const x = M.vertcat(x1, x2);\n  const u = M.MX.sym(\"u\");\n  const xdot = M.vertcat(M.plus(M.minus(M.times(M.minus(1, M.times(x2, x2)), x1), x2), u), x1);\n\n  // Sum-of-squares distance from the origin\n  const y = M.plus(M.times(x1, x1), M.times(x2, x2));\n\n  // Time horizon, discretization\n  const N = 10;\n  const T = 10.0;\n  const tgrid = [];\n  for (let k = 0; k <= N; k++) tgrid.push((T * k) / N);\n\n  // Integrate, also calculating the integral of y (substitute rk for cvodes)\n  const dae = { x: x, u: u, ode: xdot, quad: y };\n  const F = M.integrator(\"F\", \"rk\", dae, tgrid[0], tgrid.slice(1), { simplify: true });\n\n  // Pointwise values of y\n  const yfun = new M.Function(\"yfun\", [x], [y], [\"x\"], [\"y\"]);\n\n  // Initial conditions and piecewise-constant controls\n  const uvals = [];\n  for (let k = 0; k < N; k++) uvals.push(-1 + (2 * k) / (N - 1));\n  const x0 = M.DM([0, 0]);\n\n  // Simulate\n  const Fk = F.call({ x0: x0, u: M.DM([uvals]) });\n  let xf = Fk[\"xf\"];\n  let qf = Fk[\"qf\"];\n\n  // Prepend the state at the initial time\n  xf = M.horzcat(x0, xf);\n  qf = M.horzcat(M.DM(0), qf);\n\n  // y at each grid point\n  const yf = yfun.call([xf])[0];\n\n  const x_sim = xf.nonzeros();         // column-major: [x1_0,x2_0,x1_1,x2_1,...]\n  const y_sim = yf.nonzeros();\n  const q_sim = qf.nonzeros();\n\n  log(\"-----\");\n  log(\"x1 = \" + x_sim.filter((_, i) => i % 2 === 0).map((v) => v.toFixed(4)).join(\" \"));\n  log(\"x2 = \" + x_sim.filter((_, i) => i % 2 === 1).map((v) => v.toFixed(4)).join(\" \"));\n  log(\"y  = \" + y_sim.map((v) => v.toFixed(4)).join(\" \"));\n  log(\"integral of y (quadrature) = \" + q_sim.map((v) => v.toFixed(4)).join(\" \"));\n\n  // Compare integral with a Riemann sum of the pointwise y values\n  let acc = 0;\n  const cum = y_sim.map((v) => (acc += (T / N) * v));\n  log(\"integral of y (cumsum)     = \" + cum.map((v) => v.toFixed(4)).join(\" \"));\n}\n\nif (typeof require !== \"undefined\" && typeof module !== \"undefined\" && require.main === module) {\n  const path = require(\"path\");\n  const casadiPath = process.env.CASADI_JS\n    || path.resolve(__dirname, \"../../../build-wasm/swig/wasm-js/casadi.js\");\n  require(casadiPath)()\n    .then((M) => example(M, (...a) => console.log(...a)))\n    .catch((e) => { console.error(\"FATAL:\", e.message || e); process.exit(1); });\n}\n\nif (typeof module !== \"undefined\" && module.exports) module.exports = example;\n",
  "nlp_codegen.js": "//\n//     MIT No Attribution\n//\n//     Copyright (C) 2010-2023 Joel Andersson, Joris Gillis, Moritz Diehl, KU Leuven.\n//\n//     Permission is hereby granted, free of charge, to any person obtaining a copy of this\n//     software and associated documentation files (the \"Software\"), to deal in the Software\n//     without restriction, including without limitation the rights to use, copy, modify,\n//     merge, publish, distribute, sublicense, and/or sell copies of the Software, and to\n//     permit persons to whom the Software is furnished to do so.\n//\n//     THE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED,\n//     INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A\n//     PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT\n//     HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION\n//     OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE\n//     SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.\n//\n//\n// JS port of docs/examples/python/nlp_codegen.py.\n//\n// Solve a tiny NLP and generate self-contained C code for its functions.\n//\n// JS notes (see README.md):\n//   * The Python example JIT-compiles the NLP and reloads it as an\n//     external() shared library.  The wasm build ships no C compiler, so\n//     we cannot compile+load.  Instead we show the portable half: emit the\n//     C source via CodeGenerator and log a preview of it.\n\nasync function example(M, log) {\n  // Test problem:  min x^2 + y^2  s.t.  x + y - 10 = 0\n  const x = M.MX.sym(\"x\");\n  const y = M.MX.sym(\"y\");\n  const f = M.plus(M.times(x, x), M.times(y, y));\n  const g = M.minus(M.plus(x, y), 10);\n  const nlp = { x: M.vertcat(x, y), f: f, g: g };\n\n  // Create an NLP solver instance\n  const solver = M.nlpsol(\"solver\", \"ipopt\", nlp);\n\n  // Solve the NLP\n  const res = solver.call({ lbx: M.DM(-Infinity), ubx: M.DM(Infinity), lbg: M.DM(0), ubg: M.DM(0), x0: M.DM(0) });\n\n  log(\"-----\");\n  log(\"objective at solution = \" + res[\"f\"].nonzeros().join(\" \"));\n  log(\"primal solution = \" + res[\"x\"].nonzeros().join(\" \"));\n  log(\"dual solution (x) = \" + res[\"lam_x\"].nonzeros().join(\" \"));\n  log(\"dual solution (g) = \" + res[\"lam_g\"].nonzeros().join(\" \"));\n\n  // Generate C code for the NLP functions (cannot compile/load here).\n  const cg = new M.CodeGenerator(\"nlp.c\");\n  cg.add(solver);\n  const code = cg.dump();\n  const lines = code.split(\"\\n\");\n  log(\"-----\");\n  log(\"generated nlp.c (\" + lines.length + \" lines); first lines:\");\n  for (const line of lines.slice(0, 12)) log(\"  \" + line);\n}\n\nif (typeof require !== \"undefined\" && typeof module !== \"undefined\" && require.main === module) {\n  const path = require(\"path\");\n  const casadiPath = process.env.CASADI_JS\n    || path.resolve(__dirname, \"../../../build-wasm/swig/wasm-js/casadi.js\");\n  require(casadiPath)()\n    .then((M) => example(M, (...a) => console.log(...a)))\n    .catch((e) => { console.error(\"FATAL:\", e.message || e); process.exit(1); });\n}\n\nif (typeof module !== \"undefined\" && module.exports) module.exports = example;\n",
  "nlp_sensitivities.js": "//\n//     MIT No Attribution\n//\n//     Copyright (C) 2010-2023 Joel Andersson, Joris Gillis, Moritz Diehl, KU Leuven.\n//\n//     Permission is hereby granted, free of charge, to any person obtaining a copy of this\n//     software and associated documentation files (the \"Software\"), to deal in the Software\n//     without restriction, including without limitation the rights to use, copy, modify,\n//     merge, publish, distribute, sublicense, and/or sell copies of the Software, and to\n//     permit persons to whom the Software is furnished to do so.\n//\n//     THE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED,\n//     INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A\n//     PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT\n//     HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION\n//     OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE\n//     SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.\n//\n//\n// JS port of docs/examples/python/nlp_sensitivities.py.\n//\n// Direct-collocation Van der Pol OCP parametrized by a perturbation P of\n// the initial state, then sensitivities of the optimum w.r.t. P via three\n// routes: solver.factory (Hessian), solver.forward, solver.reverse, with a\n// finite-difference cross-check.\n//\n// JS notes (see README.md):\n//   * numpy poly1d/polyder/polyint replaced by small array-based helpers.\n//   * matplotlib output is dropped; we log the sensitivities instead.\n\n// Polynomial helpers (coeffs highest-degree-first, like numpy.poly1d).\nfunction polymul(a, b) {\n  const r = new Array(a.length + b.length - 1).fill(0);\n  for (let i = 0; i < a.length; i++)\n    for (let j = 0; j < b.length; j++) r[i + j] += a[i] * b[j];\n  return r;\n}\nfunction polyval(p, x) { let r = 0; for (const c of p) r = r * x + c; return r; }\nfunction polyder(p) {\n  const n = p.length - 1, r = [];\n  for (let i = 0; i < n; i++) r.push(p[i] * (n - i));\n  return r.length ? r : [0];\n}\nfunction polyint(p) {\n  const n = p.length, r = [];\n  for (let i = 0; i < n; i++) r.push(p[i] / (n - i));\n  r.push(0);\n  return r;\n}\n\nasync function example(M, log) {\n  // Degree of interpolating polynomial\n  const d = 3;\n  const tau_root = [0, ...M.collocation_points(d, \"legendre\")];\n\n  // Collocation / continuity / quadrature coefficients\n  const C = Array.from({ length: d + 1 }, () => new Array(d + 1).fill(0));\n  const D = new Array(d + 1).fill(0);\n  const B = new Array(d + 1).fill(0);\n  for (let j = 0; j <= d; j++) {\n    let p = [1];\n    for (let r = 0; r <= d; r++)\n      if (r !== j) p = polymul(p, [1, -tau_root[r]]).map((c) => c / (tau_root[j] - tau_root[r]));\n    D[j] = polyval(p, 1.0);\n    const pder = polyder(p);\n    for (let r = 0; r <= d; r++) C[j][r] = polyval(pder, tau_root[r]);\n    B[j] = polyval(polyint(p), 1.0);\n  }\n\n  // Time horizon\n  const T = 10.0;\n\n  // Model variables\n  const x1 = M.SX.sym(\"x1\");\n  const x2 = M.SX.sym(\"x2\");\n  const x = M.vertcat(x1, x2);\n  const u = M.SX.sym(\"u\");\n  const xdot = M.vertcat(M.plus(M.minus(M.times(M.minus(1, M.times(x2, x2)), x1), x2), u), x1);\n  const L = M.plus(M.plus(M.times(x1, x1), M.times(x2, x2)), M.times(u, u));\n  const f = new M.Function(\"f\", [x, u], [xdot, L], [\"x\", \"u\"], [\"xdot\", \"L\"]);\n\n  // Control discretization\n  const N = 20;\n  const h = T / N;\n\n  // Empty NLP\n  const w = [], w0 = [], lbw = [], ubw = [];\n  let J = M.MX(0);\n  const g = [], lbg = [], ubg = [];\n  const x_plot = [], u_plot = [];\n\n  // \"Lift\" initial conditions\n  let Xk = M.MX.sym(\"X0\", 2);\n  w.push(Xk); lbw.push(0, 1); ubw.push(0, 1); w0.push(0, 1); x_plot.push(Xk);\n\n  // Perturb with P\n  const P = M.MX.sym(\"P\", 2);\n  Xk = M.plus(Xk, P);\n\n  // Formulate the NLP\n  for (let k = 0; k < N; k++) {\n    const Uk = M.MX.sym(\"U_\" + k);\n    w.push(Uk); lbw.push(-1); ubw.push(0.85); w0.push(0); u_plot.push(Uk);\n\n    const Xc = [];\n    for (let j = 0; j < d; j++) {\n      const Xkj = M.MX.sym(\"X_\" + k + \"_\" + j, 2);\n      Xc.push(Xkj); w.push(Xkj);\n      lbw.push(-0.25, -Infinity); ubw.push(Infinity, Infinity); w0.push(0, 0);\n    }\n\n    let Xk_end = M.times(D[0], Xk);\n    for (let j = 1; j <= d; j++) {\n      let xp = M.times(C[0][j], Xk);\n      for (let r = 0; r < d; r++) xp = M.plus(xp, M.times(C[r + 1][j], Xc[r]));\n      const fj = f.call([Xc[j - 1], Uk]);\n      g.push(M.minus(M.times(h, fj[0]), xp)); lbg.push(0, 0); ubg.push(0, 0);\n      Xk_end = M.plus(Xk_end, M.times(D[j], Xc[j - 1]));\n      J = M.plus(J, M.times(B[j], M.times(fj[1], h)));\n    }\n\n    Xk = M.MX.sym(\"X_\" + (k + 1), 2);\n    w.push(Xk); lbw.push(-0.25, -Infinity); ubw.push(Infinity, Infinity); w0.push(0, 0);\n    x_plot.push(Xk);\n    g.push(M.minus(Xk_end, Xk)); lbg.push(0, 0); ubg.push(0, 0);\n  }\n\n  const W = M.vcat(w);\n  const G = M.vcat(g);\n\n  // NLP, using SQP + active-set QP for accurate multipliers\n  const prob = { f: J, x: W, g: G, p: P };\n  const opts = {\n    // qpoases is shipped as a browser-loadable conic plugin. The qrqp backend\n    // loads the QR linear solver synchronously from a nested dependency in\n    // this WASM build, which browsers cannot do.\n    qpsol: \"qpoases\",\n    qpsol_options: { printLevel: \"none\" },\n    print_time: false,\n  };\n  const solver = M.nlpsol(\"solver\", \"sqpmethod\", prob, opts);\n\n  const DMlbw = M.DM(lbw), DMubw = M.DM(ubw), DMlbg = M.DM(lbg), DMubg = M.DM(ubg);\n\n  // Solve the NLP\n  const sol = solver.call({ x0: M.DM(w0), lbx: DMlbw, ubx: DMubw, lbg: DMlbg, ubg: DMubg, p: M.DM(0) });\n  log(\"-----\");\n  log(\"objective at solution = \" + sol[\"f\"].nonzeros().join(\" \"));\n\n  const nx = Number(W.size1());\n  const ng = Number(G.size1());\n\n  // High-level: Hessian of optimal f w.r.t. p via factory\n  const hsolver = solver.factory(\"h\", solver.name_in(), [\"hess:f:p:p\"]);\n  log(\"hsolver generated\");\n  const hsol = hsolver.call({\n    x0: sol[\"x\"], lam_x0: sol[\"lam_x\"], lam_g0: sol[\"lam_g\"],\n    lbx: DMlbw, ubx: DMubw, lbg: DMlbg, ubg: DMubg, p: M.DM(0),\n  });\n  log(\"Hessian of f w.r.t. p (2x2) = \" + hsol[\"hess_f_p_p\"].nonzeros().map((v) => v.toFixed(6)).join(\" \"));\n\n  // Low-level forward AD: two directions at once\n  const nfwd = 2;\n  const zx = M.DM.zeros(nx, 1);\n  const zg = M.DM.zeros(ng, 1);\n  const fwd_lbx = M.DM.zeros(nx, nfwd);\n  const fwd_ubx = M.DM.zeros(nx, nfwd);\n  const fwd_lbg = M.DM.zeros(ng, nfwd);\n  const fwd_ubg = M.DM.zeros(ng, nfwd);\n  const fwd_p = M.DM.zeros(2, nfwd);   // perturb P\n  fwd_p.set(1, false, 0, 0);           // fwd_p[0][0] = 1\n  fwd_p.set(1, false, 1, 1);           // fwd_p[1][1] = 1\n\n  const fwd_solver = solver.forward(nfwd);\n  log(\"fwd_solver generated\");\n  const sol_fwd = fwd_solver.call({\n    out_x: sol[\"x\"], out_lam_g: sol[\"lam_g\"], out_lam_x: sol[\"lam_x\"],\n    out_f: sol[\"f\"], out_g: sol[\"g\"], lbx: DMlbw, ubx: DMubw, lbg: DMlbg, ubg: DMubg,\n    fwd_lbx: fwd_lbx, fwd_ubx: fwd_ubx, fwd_lbg: fwd_lbg, fwd_ubg: fwd_ubg,\n    p: M.DM(0), fwd_p: fwd_p,\n  });\n\n  // Finite-difference cross-check of d f / d P\n  const hfd = 1e-3;\n  const fdpert = [];\n  for (let dir = 0; dir < nfwd; dir++) {\n    const dp = M.DM([dir === 0 ? hfd : 0, dir === 1 ? hfd : 0]);\n    const r = solver.call({\n      x0: sol[\"x\"], lam_g0: sol[\"lam_g\"], lam_x0: sol[\"lam_x\"],\n      lbx: DMlbw, ubx: DMubw, lbg: DMlbg, ubg: DMubg, p: dp,\n    });\n    fdpert.push(r[\"f\"].nonzeros()[0]);\n  }\n  const f0 = sol[\"f\"].nonzeros()[0];\n  log(\"-----\");\n  log(\"d f / d P (finite differences) = \" + fdpert.map((v) => ((v - f0) / hfd).toFixed(6)).join(\" \"));\n  log(\"d f / d P (forward AD)         = \" + sol_fwd[\"fwd_f\"].nonzeros().map((v) => v.toFixed(6)).join(\" \"));\n\n  // Reverse AD: which inputs influence f\n  const nadj = 1;\n  const adj_f = M.DM.zeros(1, nadj);\n  adj_f.set(1, false, 0, 0);\n  const adj_solver = solver.reverse(nadj);\n  log(\"adj_solver generated\");\n  const sol_adj = adj_solver.call({\n    out_x: sol[\"x\"], out_lam_g: sol[\"lam_g\"], out_lam_x: sol[\"lam_x\"],\n    out_f: sol[\"f\"], out_g: sol[\"g\"], lbx: DMlbw, ubx: DMubw, lbg: DMlbg, ubg: DMubg,\n    adj_f: adj_f, adj_g: M.DM.zeros(ng, nadj), p: M.DM(0), adj_x: M.DM.zeros(nx, nadj),\n  });\n  log(\"d f / d P (reverse AD)         = \" + sol_adj[\"adj_p\"].nonzeros().map((v) => v.toFixed(6)).join(\" \"));\n}\n\nif (typeof require !== \"undefined\" && typeof module !== \"undefined\" && require.main === module) {\n  const path = require(\"path\");\n  const casadiPath = process.env.CASADI_JS\n    || path.resolve(__dirname, \"../../../build-wasm/swig/wasm-js/casadi.js\");\n  require(casadiPath)()\n    .then((M) => example(M, (...a) => console.log(...a)))\n    .catch((e) => { console.error(\"FATAL:\", e.message || e); process.exit(1); });\n}\n\nif (typeof module !== \"undefined\" && module.exports) module.exports = example;\n",
  "parallel_map.js": "//\n//     MIT No Attribution\n//\n//     Copyright (C) 2010-2023 Joel Andersson, Joris Gillis, Moritz Diehl, KU Leuven.\n//\n//     Permission is hereby granted, free of charge, to any person obtaining a copy of this\n//     software and associated documentation files (the \"Software\"), to deal in the Software\n//     without restriction, including without limitation the rights to use, copy, modify,\n//     merge, publish, distribute, sublicense, and/or sell copies of the Software, and to\n//     permit persons to whom the Software is furnished to do so.\n//\n//     THE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED,\n//     INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A\n//     PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT\n//     HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION\n//     OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE\n//     SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.\n//\n//\n// JS port of docs/examples/python/parallel_map.py.\n//\n// Evaluate a function over many inputs, comparing a hand-written vertcat\n// of N calls against Function.map(N).\n//\n// JS notes (see README.md):\n//   * The Python example also tries f.map(N, \"openmp\"); the wasm build is\n//     single-threaded, so we use only the default (serial) map and note it.\n//   * The expensive function uses 2000 nested sin() here (vs 100000) to keep\n//     the in-browser/node run snappy.\n\nasync function example(M, log) {\n  // Number of inputs to evaluate\n  const N = 300;\n\n  // Dummy input\n  const dummyInput = [];\n  for (let k = 0; k < N; k++) dummyInput.push((2.0 * Math.PI * k) / (N - 1));\n\n  // A moderately expensive function: nested sines\n  log(\"creating dummy function...\");\n  const x = M.SX.sym(\"x\");\n  let y = x;\n  for (let k = 0; k < 2000; k++) y = M.sin(y);\n  const f0 = new M.Function(\"f\", [x], [y]);\n\n  // Evaluate serially, the old-fashioned way (vertcat of N scalar calls)\n  const X = M.MX.sym(\"x\", N);\n  const [...Xs] = M.vertsplit(X);\n  const Y = M.vertcat(...Xs.map((xk) => f0.call([xk])[0]));\n  const fNaiveParallel = new M.Function(\"fParallel\", [X], [Y]);\n\n  log(\"evaluating naive parallel function...\");\n  let t0 = Date.now();\n  const outNaive = fNaiveParallel.call([M.DM(dummyInput)])[0];\n  log(\"evaluated naive parallel function in \" + ((Date.now() - t0) / 1000).toFixed(3) + \" seconds\");\n\n  // Evaluate it using the serial map construct\n  const fMap = f0.map(N);\n  log(\"evaluating serial map function...\");\n  t0 = Date.now();\n  const outMap = fMap.call([M.DM([dummyInput])])[0];\n  log(\"evaluated serial map function in \" + ((Date.now() - t0) / 1000).toFixed(3) + \" seconds\");\n\n  // The two have differently-shaped outputs (column vs row); compare values.\n  const a = outNaive.nonzeros();\n  const b = outMap.nonzeros();\n  let maxdiff = 0;\n  for (let i = 0; i < a.length; i++) maxdiff = Math.max(maxdiff, Math.abs(a[i] - b[i]));\n  log(\"-----\");\n  log(\"max |naive - map| = \" + maxdiff);\n  log(\"first 5 outputs = \" + b.slice(0, 5).map((v) => v.toFixed(6)).join(\" \"));\n}\n\nif (typeof require !== \"undefined\" && typeof module !== \"undefined\" && require.main === module) {\n  const path = require(\"path\");\n  const casadiPath = process.env.CASADI_JS\n    || path.resolve(__dirname, \"../../../build-wasm/swig/wasm-js/casadi.js\");\n  require(casadiPath)()\n    .then((M) => example(M, (...a) => console.log(...a)))\n    .catch((e) => { console.error(\"FATAL:\", e.message || e); process.exit(1); });\n}\n\nif (typeof module !== \"undefined\" && module.exports) module.exports = example;\n",
  "race_car.js": "//\n//     MIT No Attribution\n//\n//     Copyright (C) 2010-2023 Joel Andersson, Joris Gillis, Moritz Diehl, KU Leuven.\n//\n//     Permission is hereby granted, free of charge, to any person obtaining a copy of this\n//     software and associated documentation files (the \"Software\"), to deal in the Software\n//     without restriction, including without limitation the rights to use, copy, modify,\n//     merge, publish, distribute, sublicense, and/or sell copies of the Software, and to\n//     permit persons to whom the Software is furnished to do so.\n//\n//     THE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED,\n//     INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A\n//     PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT\n//     HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION\n//     OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE\n//     SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.\n//\n//\n// JS port of docs/examples/python/race_car.py.\n//\n// Car race along a track: a minimal-time OCP solved with direct\n// multiple-shooting via the Opti stack (fully portable).\n//\n// JS notes (see README.md):\n//   * Column slices X[:,k] come from M.horzsplit(X); rows from M.vertsplit.\n//   * matplotlib output is dropped; we log the optimum instead.\n\nasync function example(M, log) {\n  const pi = Math.PI;\n  const N = 100; // number of control intervals\n\n  const opti = new M.Opti();\n\n  // ---- decision variables ---------\n  const X = opti.variable(2, N + 1);      // state trajectory\n  const Xc = M.horzsplit(X);              // columns X[:,k]\n  const [posRow, speedRow] = M.vertsplit(X); // rows\n  const U = opti.variable(1, N);          // control trajectory (throttle)\n  const Uc = M.horzsplit(U);\n  const T = opti.variable();              // final time\n\n  // ---- objective ---------\n  opti.minimize(T); // race in minimal time\n\n  // ---- dynamic constraints --------\n  // dx/dt = f(x,u) = [x1, u - x1]\n  const f = (x, u) => {\n    const [, x1] = M.vertsplit(x);\n    return M.vertcat(x1, M.minus(u, x1));\n  };\n\n  const dt = M.rdivide(T, N); // length of a control interval\n  for (let k = 0; k < N; k++) {\n    const xk = Xc[k], uk = Uc[k];\n    // Runge-Kutta 4 integration\n    const k1 = f(xk, uk);\n    const k2 = f(M.plus(xk, M.times(M.rdivide(dt, 2), k1)), uk);\n    const k3 = f(M.plus(xk, M.times(M.rdivide(dt, 2), k2)), uk);\n    const k4 = f(M.plus(xk, M.times(dt, k3)), uk);\n    const sum = M.plus(M.plus(k1, M.times(2, k2)), M.plus(M.times(2, k3), k4));\n    const x_next = M.plus(xk, M.times(M.rdivide(dt, 6), sum));\n    opti.subject_to(M.eq(Xc[k + 1], x_next)); // close the gaps\n  }\n\n  // ---- path constraints -----------\n  const limit = (p) => M.minus(1, M.rdivide(M.sin(M.times(2 * pi, p)), 2));\n  opti.subject_to(M.le(speedRow, limit(posRow)));   // track speed limit\n  opti.subject_to(M.le(0, U));                      // control is limited ...\n  opti.subject_to(M.le(U, 1));                      // ... to [0, 1]\n\n  // ---- boundary conditions --------\n  const posSplit = M.horzsplit(posRow); // scalars along the row\n  const speedSplit = M.horzsplit(speedRow);\n  opti.subject_to(M.eq(posSplit[0], 0));      // start at position 0 ...\n  opti.subject_to(M.eq(speedSplit[0], 0));    // ... from stand-still\n  opti.subject_to(M.eq(posSplit[N], 1));      // finish line at position 1\n\n  // ---- misc. constraints ----------\n  opti.subject_to(M.ge(T, 0)); // Time must be positive\n\n  // ---- initial values for solver ---\n  opti.set_initial(speedRow, 1);\n  opti.set_initial(T, 1);\n\n  // ---- solve NLP ------\n  opti.solver(\"ipopt\");\n  const sol = opti.solve();\n\n  // ---- post-processing ------\n  log(\"-----\");\n  log(\"minimal time T = \" + sol.value(T).nonzeros().join(\" \"));\n  log(\"speed = \" + sol.value(speedRow).nonzeros().map((v) => v.toFixed(4)).join(\" \"));\n  log(\"pos   = \" + sol.value(posRow).nonzeros().map((v) => v.toFixed(4)).join(\" \"));\n  log(\"throttle U = \" + sol.value(U).nonzeros().map((v) => v.toFixed(4)).join(\" \"));\n}\n\nif (typeof require !== \"undefined\" && typeof module !== \"undefined\" && require.main === module) {\n  const path = require(\"path\");\n  const casadiPath = process.env.CASADI_JS\n    || path.resolve(__dirname, \"../../../build-wasm/swig/wasm-js/casadi.js\");\n  require(casadiPath)()\n    .then((M) => example(M, (...a) => console.log(...a)))\n    .catch((e) => { console.error(\"FATAL:\", e.message || e); process.exit(1); });\n}\n\nif (typeof module !== \"undefined\" && module.exports) module.exports = example;\n",
  "rocket.js": "//\n//     MIT No Attribution\n//\n//     Copyright (C) 2010-2023 Joel Andersson, Joris Gillis, Moritz Diehl, KU Leuven.\n//\n//     Permission is hereby granted, free of charge, to any person obtaining a copy of this\n//     software and associated documentation files (the \"Software\"), to deal in the Software\n//     without restriction, including without limitation the rights to use, copy, modify,\n//     merge, publish, distribute, sublicense, and/or sell copies of the Software, and to\n//     permit persons to whom the Software is furnished to do so.\n//\n//     THE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED,\n//     INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A\n//     PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT\n//     HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION\n//     OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE\n//     SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.\n//\n//\n// JS port of docs/examples/python/rocket.py.\n//\n// Rocket trajectory NLP: discretize the ODE with explicit Euler and let\n// ipopt pick the throttle for each of 50 segments (fully portable).\n//\n// JS notes (see README.md):\n//   * matplotlib output is dropped; we log the optimum instead.\n//   * The Python `expand=True` option is dropped: under the wasm build it\n//     crashes the GC teardown. The solution is identical without it.\n\nasync function example(M, log) {\n  // Control\n  const u = M.MX.sym(\"u\");\n\n  // State\n  const x = M.MX.sym(\"x\", 3);\n  const [s, v, m] = M.vertsplit(x); // position, speed, mass\n\n  // ODE right hand side\n  const sdot = v;\n  const vdot = M.rdivide(M.minus(u, M.times(0.05, M.times(v, v))), m);\n  const mdot = M.times(-0.1, M.times(u, u));\n  const xdot = M.vertcat(sdot, vdot, mdot);\n\n  // ODE right hand side function\n  const f = new M.Function(\"f\", [x, u], [xdot]);\n\n  // Integrate with Explicit Euler over 0.2 seconds\n  const dt = 0.01; // Time step\n  let xj = x;\n  for (let j = 0; j < 20; j++) {\n    const fj = f.call([xj, u])[0];\n    xj = M.plus(xj, M.times(dt, fj));\n  }\n\n  // Discrete time dynamics function\n  const F = new M.Function(\"F\", [x, u], [xj]);\n\n  // Number of control segments\n  const nu = 50;\n\n  // Control for all segments\n  const U = M.MX.sym(\"U\", nu);\n  const Us = M.vertsplit(U);\n\n  // Initial conditions\n  const X0 = M.MX([0, 0, 1]);\n\n  // Integrate over all intervals\n  let X = X0;\n  for (let k = 0; k < nu; k++) X = F.call([X, Us[k]])[0];\n\n  // Objective function and constraints\n  const J = M.dot(U, U);                 // u'*u\n  const G = M.vertcat(...M.vertsplit(X).slice(0, 2)); // x(0:2)\n\n  // NLP\n  const nlp = { x: U, f: J, g: G };\n\n  // Allocate an NLP solver\n  const solver = M.nlpsol(\"solver\", \"ipopt\", nlp, { \"ipopt.tol\": 1e-10 });\n\n  // Bounds on u, initial condition, and bounds on g; solve\n  const res = solver.call({\n    lbx: -0.5, ubx: 0.5, x0: 0.4,\n    lbg: M.DM([10, 0]), ubg: M.DM([10, 0]),\n  });\n\n  log(\"-----\");\n  log(\"objective at solution = \" + res[\"f\"].nonzeros().join(\" \"));\n  log(\"u_opt = \" + res[\"x\"].nonzeros().map((v) => v.toFixed(4)).join(\" \"));\n  log(\"lam_x = \" + res[\"lam_x\"].nonzeros().map((v) => v.toFixed(4)).join(\" \"));\n}\n\nif (typeof require !== \"undefined\" && typeof module !== \"undefined\" && require.main === module) {\n  const path = require(\"path\");\n  const casadiPath = process.env.CASADI_JS\n    || path.resolve(__dirname, \"../../../build-wasm/swig/wasm-js/casadi.js\");\n  require(casadiPath)()\n    .then((M) => example(M, (...a) => console.log(...a)))\n    .catch((e) => { console.error(\"FATAL:\", e.message || e); process.exit(1); });\n}\n\nif (typeof module !== \"undefined\" && module.exports) module.exports = example;\n",
  "rosenbrock.js": "//\n//     MIT No Attribution\n//\n//     Copyright (C) 2010-2023 Joel Andersson, Joris Gillis, Moritz Diehl, KU Leuven.\n//\n//     Permission is hereby granted, free of charge, to any person obtaining a copy of this\n//     software and associated documentation files (the \"Software\"), to deal in the Software\n//     without restriction, including without limitation the rights to use, copy, modify,\n//     merge, publish, distribute, sublicense, and/or sell copies of the Software, and to\n//     permit persons to whom the Software is furnished to do so.\n//\n//     THE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED,\n//     INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A\n//     PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT\n//     HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION\n//     OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE\n//     SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.\n//\n//\n// JS port of docs/examples/python/rosenbrock.py.\n//\n// Solve the Rosenbrock problem, formulated as the NLP:\n//\n//   minimize     x^2 + 100*z^2\n//   subject to   z + (1-x)^2 - y == 0\n//\n// CasADi-in-JS notes (see README.md for the full list):\n//   * No operator overloading.  Use free-function forms:\n//       x*x   -> M.times(x, x)        1 - x -> M.minus(M.SX(1), x)\n//       a + b -> M.plus(a, b)         x**2  -> M.power(x, M.SX(2))\n//     Number literals in binary ops must be wrapped explicitly\n//     (M.SX/M.MX/M.DM) -- there is no Python-style __radd__ coercion.\n//   * Concat: M.vertcat(x, y, z) is variadic; M.vcat([x, y, z]) takes\n//     a list.  (Bare M.vertcat([x, y, z]) is a 1-arg list call.)\n//   * Solver IO are name-keyed objects (x0/lbg/ubg... -> x/f/g/...),\n//     same as Python dicts.\n//   * M.DM values read out via .nonzeros() -> number[].\n\n// The example body is environment-agnostic: it receives the loaded\n// casadi module `M` and a `log(...)` sink, so the SAME file runs both\n// under Node (see the self-run block below) and in the browser (where\n// rosenbrock.html calls example()).  Keep this function pure casadi.\nasync function example(M, log) {\n  // Declare variables\n  const x = M.SX.sym(\"x\");\n  const y = M.SX.sym(\"y\");\n  const z = M.SX.sym(\"z\");\n\n  // Formulate the NLP\n  const one = M.SX(1), c100 = M.SX(100);\n  const f = M.plus(M.times(x, x), M.times(c100, M.times(z, z)));\n  const oneMinusX = M.minus(one, x);\n  const g = M.minus(M.plus(z, M.times(oneMinusX, oneMinusX)), y);\n  const nlp = { x: M.vertcat(x, y, z), f: f, g: g };\n\n  // Create an NLP solver\n  const solver = M.nlpsol(\"solver\", \"ipopt\", nlp);\n\n  // Solve the Rosenbrock problem\n  const res = solver.call({\n    x0:  M.DM([2.5, 3.0, 0.75]),\n    ubg: M.DM(0),\n    lbg: M.DM(0),\n  });\n\n  // Print solution\n  const fmt = (label, val) => log(label.padStart(50) + \" \" + val.nonzeros().join(\" \"));\n  log(\"\");\n  fmt(\"Optimal cost:\",                     res[\"f\"]);\n  fmt(\"Primal solution:\",                  res[\"x\"]);\n  fmt(\"Dual solution (simple bounds):\",    res[\"lam_x\"]);\n  fmt(\"Dual solution (nonlinear bounds):\", res[\"lam_g\"]);\n}\n\n// ---- Node entry point: `node rosenbrock.js` --------------------------\n// Skipped in the browser, where `require` is undefined and rosenbrock.html\n// drives example() instead.\nif (typeof require !== \"undefined\" && typeof module !== \"undefined\" && require.main === module) {\n  const path = require(\"path\");\n  const casadiPath = process.env.CASADI_JS\n    || path.resolve(__dirname, \"../../../build-wasm/swig/wasm-js/casadi.js\");\n  require(casadiPath)()\n    .then((M) => example(M, (...a) => console.log(...a)))\n    .catch((e) => { console.error(\"FATAL:\", e.message || e); process.exit(1); });\n}\n\nif (typeof module !== \"undefined\" && module.exports) module.exports = example;\n",
  "sensitivity_analysis.js": "//\n//     MIT No Attribution\n//\n//     Copyright (C) 2010-2023 Joel Andersson, Joris Gillis, Moritz Diehl, KU Leuven.\n//\n//     Permission is hereby granted, free of charge, to any person obtaining a copy of this\n//     software and associated documentation files (the \"Software\"), to deal in the Software\n//     without restriction, including without limitation the rights to use, copy, modify,\n//     merge, publish, distribute, sublicense, and/or sell copies of the Software, and to\n//     permit persons to whom the Software is furnished to do so.\n//\n//     THE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED,\n//     INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A\n//     PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT\n//     HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION\n//     OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE\n//     SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.\n//\n//\n// JS port of docs/examples/python/sensitivity_analysis.py.\n//\n// Forward / adjoint / second-order integrator sensitivities obtained with\n// Function.factory and compared against finite differences.\n//\n// JS notes (see README.md):\n//   * The Python script also loops over a DAE example with the \"idas\" and\n//     \"cvodes\" integrators and a \"kinsol\" root-finder; all three abort the\n//     wasm runtime, so only the ODE (rocket) example is ported here, run\n//     with the \"rk\" and \"collocation\" integrators (which support sensitivity\n//     factories just fine).\n\nasync function example(M, log) {\n  log(\"Testing sensitivity analysis in CasADi\");\n  log(\"******\");\n  log(\"Testing ODE example\");\n\n  // Time\n  const t = M.SX.sym(\"t\");\n  // Parameter\n  const u = M.SX.sym(\"u\");\n  // Differential states\n  const s = M.SX.sym(\"s\"), v = M.SX.sym(\"v\"), m = M.SX.sym(\"m\");\n  const x = M.vertcat(s, v, m);\n\n  // Constants\n  const alpha = 0.05; // friction\n  const beta = 0.1;   // fuel consumption rate\n\n  // Differential equation\n  const ode = M.vertcat(\n    v,\n    M.rdivide(M.minus(u, M.times(alpha, M.times(v, v))), m),\n    M.times(-beta, M.times(u, u)));\n\n  // Quadrature\n  const quad = M.plus(M.power(v, 3), M.power(M.minus(M.minus(3, M.sin(t)), u), 2));\n\n  // DAE callback\n  const dae = { t: t, x: x, p: u, ode: ode, quad: quad };\n\n  const tf = 0.5;        // Time length\n  const x0 = M.DM([0, 0, 1]); // Initial position\n  const u0 = 0.4;        // Parameter\n  const h = 0.001;       // FD step\n\n  const fmt = (dm) => dm.nonzeros().map((z) => z.toPrecision(8)).join(\", \");\n\n  for (const MyIntegrator of [\"rk\", \"collocation\"]) {\n    log(\"========\");\n    log(\"Integrator: \" + MyIntegrator);\n    log(\"========\");\n\n    // Integrator\n    const I = M.integrator(\"I\", MyIntegrator, dae, 0, tf, { number_of_finite_elements: 100 });\n\n    // Integrate to get results\n    let res = I.call({ x0: x0, p: u0 });\n    const xf = res[\"xf\"], qf = res[\"qf\"];\n    log(\"Unperturbed solution: xf = [\" + fmt(xf) + \"], qf = [\" + fmt(qf) + \"]\");\n\n    // Finite-difference approximation\n    res = I.call({ x0: x0, p: u0 + h });\n    const fd_xf = M.rdivide(M.minus(res[\"xf\"], xf), h);\n    const fd_qf = M.rdivide(M.minus(res[\"qf\"], qf), h);\n    log(\"Finite difference: d(xf)/d(p) = [\" + fmt(fd_xf) + \"], d(qf)/d(p) = [\" + fmt(fd_qf) + \"]\");\n\n    // Forward sensitivities\n    const I_fwd = I.factory(\"I_fwd\", [\"x0\", \"z0\", \"p\", \"fwd:p\"], [\"fwd:xf\", \"fwd:qf\"]);\n    res = I_fwd.call({ x0: x0, p: u0, fwd_p: 1 });\n    log(\"Forward: d(xf)/d(p) = [\" + fmt(res[\"fwd_xf\"]) + \"], d(qf)/d(p) = [\" + fmt(res[\"fwd_qf\"]) + \"]\");\n\n    // Adjoint sensitivities\n    const I_adj = I.factory(\"I_adj\", [\"x0\", \"z0\", \"p\", \"adj:qf\"], [\"adj:x0\", \"adj:p\"]);\n    res = I_adj.call({ x0: x0, p: u0, adj_qf: 1 });\n    let adj_x0 = res[\"adj_x0\"], adj_p = res[\"adj_p\"];\n    log(\"Adjoint: d(qf)/d(x0) = [\" + fmt(adj_x0) + \"], d(qf)/d(p) = [\" + fmt(adj_p) + \"]\");\n\n    // FD of adjoint -> second order\n    res = I_adj.call({ x0: x0, p: u0 + h, adj_qf: 1 });\n    const fd_adj_x0 = M.rdivide(M.minus(res[\"adj_x0\"], adj_x0), h);\n    const fd_adj_p = M.rdivide(M.minus(res[\"adj_p\"], adj_p), h);\n    log(\"FD of adjoint: d2(qf)/d(x0)d(p) = [\" + fmt(fd_adj_x0) + \"], d2(qf)/d(p)d(p) = [\" + fmt(fd_adj_p) + \"]\");\n\n    // Forward over adjoint -> second order\n    const I_foa = I_adj.factory(\"I_foa\", [\"x0\", \"z0\", \"p\", \"adj_qf\", \"fwd:p\"], [\"fwd:adj_x0\", \"fwd:adj_p\"]);\n    res = I_foa.call({ x0: x0, p: u0, adj_qf: 1, fwd_p: 1 });\n    log(\"Forward over adjoint: d2(qf)/d(x0)d(p) = [\" + fmt(res[\"fwd_adj_x0\"]) + \"], d2(qf)/d(p)d(p) = [\" + fmt(res[\"fwd_adj_p\"]) + \"]\");\n\n    // Adjoint over adjoint -> second order\n    const I_aoa = I_adj.factory(\"I_aoa\", [\"x0\", \"z0\", \"p\", \"adj_qf\", \"adj:adj_p\"], [\"adj:x0\", \"adj:p\"]);\n    res = I_aoa.call({ x0: x0, p: u0, adj_qf: 1, adj_adj_p: 1 });\n    log(\"Adjoint over adjoint: d2(qf)/d(x0)d(p) = [\" + fmt(res[\"adj_x0\"]) + \"], d2(qf)/d(p)d(p) = [\" + fmt(res[\"adj_p\"]) + \"]\");\n  }\n}\n\nif (typeof require !== \"undefined\" && typeof module !== \"undefined\" && require.main === module) {\n  const path = require(\"path\");\n  const casadiPath = process.env.CASADI_JS\n    || path.resolve(__dirname, \"../../../build-wasm/swig/wasm-js/casadi.js\");\n  require(casadiPath)()\n    .then((M) => example(M, (...a) => console.log(...a)))\n    .catch((e) => { console.error(\"FATAL:\", e.message || e); process.exit(1); });\n}\n\nif (typeof module !== \"undefined\" && module.exports) module.exports = example;\n",
  "simple_lp.js": "//\n//     MIT No Attribution\n//\n//     Copyright (C) 2010-2023 Joel Andersson, Joris Gillis, Moritz Diehl, KU Leuven.\n//\n//     Permission is hereby granted, free of charge, to any person obtaining a copy of this\n//     software and associated documentation files (the \"Software\"), to deal in the Software\n//     without restriction, including without limitation the rights to use, copy, modify,\n//     merge, publish, distribute, sublicense, and/or sell copies of the Software, and to\n//     permit persons to whom the Software is furnished to do so.\n//\n//     THE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED,\n//     INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A\n//     PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT\n//     HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION\n//     OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE\n//     SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.\n//\n//\n// JS port of docs/examples/python/simple_lp.py.\n//\n//   minimize    3x + 4y\n//   subject to  x + 2y <= 14\n//               3x -  y >= 0\n//                x -  y <= 2\n//\n// JS notes (see README.md):\n//   * Infinity works directly inside M.DM (renders as inf).\n//   * A linear program is a Conic (QP) problem with no quadratic term:\n//     pass only the sparsity of the constraint matrix `a`.\n\nasync function example(M, log) {\n  // Sparsity of the LP linear term (3 constraints x 2 variables)\n  const A = M.Sparsity.dense(3, 2);\n\n  // Create solver (qpoases handles LPs as a degenerate QP)\n  const solver = M.conic(\"solver\", \"qpoases\", { a: A });\n\n  const sol = solver.call({\n    g:   M.DM([3, 4]),\n    a:   M.DM([[1, 2], [3, -1], [1, -1]]),\n    lba: M.DM([-Infinity, 0, -Infinity]),\n    uba: M.DM([14, Infinity, 2]),\n  });\n\n  for (const k of Object.keys(sol)) {\n    log(k + \" = \" + sol[k].nonzeros().join(\" \"));\n  }\n}\n\nif (typeof require !== \"undefined\" && typeof module !== \"undefined\" && require.main === module) {\n  const path = require(\"path\");\n  const casadiPath = process.env.CASADI_JS\n    || path.resolve(__dirname, \"../../../build-wasm/swig/wasm-js/casadi.js\");\n  require(casadiPath)()\n    .then((M) => example(M, (...a) => console.log(...a)))\n    .catch((e) => { console.error(\"FATAL:\", e.message || e); process.exit(1); });\n}\n\nif (typeof module !== \"undefined\" && module.exports) module.exports = example;\n",
  "simple_nlp.js": "//\n//     MIT No Attribution\n//\n//     Copyright (C) 2010-2023 Joel Andersson, Joris Gillis, Moritz Diehl, KU Leuven.\n//\n//     Permission is hereby granted, free of charge, to any person obtaining a copy of this\n//     software and associated documentation files (the \"Software\"), to deal in the Software\n//     without restriction, including without limitation the rights to use, copy, modify,\n//     merge, publish, distribute, sublicense, and/or sell copies of the Software, and to\n//     permit persons to whom the Software is furnished to do so.\n//\n//     THE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED,\n//     INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A\n//     PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT\n//     HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION\n//     OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE\n//     SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.\n//\n//\n// JS port of docs/examples/python/simple_nlp.py.\n//\n//   minimize    x0^2 + x1^2\n//   subject to  x0 + x1 - 10 >= 0\n//\n// JS notes (see README.md):\n//   * Element access: Python's x[0]/x[1] becomes destructuring of\n//     M.vertsplit(x) -> [x0, x1] (a list of scalar sub-expressions).\n\nasync function example(M, log) {\n  // Declare variables\n  const x = M.SX.sym(\"x\", 2);\n  const [x0, x1] = M.vertsplit(x);\n\n  // Form the NLP\n  const f = M.plus(M.times(x0, x0), M.times(x1, x1));      // objective\n  const g = M.minus(M.plus(x0, x1), M.SX(10));             // constraint\n  const nlp = { x: x, f: f, g: g };\n\n  // Allocate an ipopt solver and solve with g >= 0\n  const solver = M.nlpsol(\"solver\", \"ipopt\", nlp);\n  const sol = solver.call({ lbg: M.DM(0) });\n\n  // Print solution\n  log(\"-----\");\n  log(\"objective at solution = \" + sol[\"f\"].nonzeros().join(\" \"));\n  log(\"primal solution = \" + sol[\"x\"].nonzeros().join(\" \"));\n  log(\"dual solution (x) = \" + sol[\"lam_x\"].nonzeros().join(\" \"));\n  log(\"dual solution (g) = \" + sol[\"lam_g\"].nonzeros().join(\" \"));\n}\n\nif (typeof require !== \"undefined\" && typeof module !== \"undefined\" && require.main === module) {\n  const path = require(\"path\");\n  const casadiPath = process.env.CASADI_JS\n    || path.resolve(__dirname, \"../../../build-wasm/swig/wasm-js/casadi.js\");\n  require(casadiPath)()\n    .then((M) => example(M, (...a) => console.log(...a)))\n    .catch((e) => { console.error(\"FATAL:\", e.message || e); process.exit(1); });\n}\n\nif (typeof module !== \"undefined\" && module.exports) module.exports = example;\n",
  "vdp_collocation.js": "//\n//     MIT No Attribution\n//\n//     Copyright (C) 2010-2023 Joel Andersson, Joris Gillis, Moritz Diehl, KU Leuven.\n//\n//     Permission is hereby granted, free of charge, to any person obtaining a copy of this\n//     software and associated documentation files (the \"Software\"), to deal in the Software\n//     without restriction, including without limitation the rights to use, copy, modify,\n//     merge, publish, distribute, sublicense, and/or sell copies of the Software, and to\n//     permit persons to whom the Software is furnished to do so.\n//\n//     THE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED,\n//     INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A\n//     PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT\n//     HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION\n//     OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE\n//     SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.\n//\n//\n// JS port of docs/examples/python/vdp_collocation.py.\n//\n// Van der Pol OCP transcribed by hand with Radau collocation; the NLP\n// variable vector V is sliced manually (no integrator plugin) -> portable.\n//\n// JS notes (see README.md):\n//   * numpy poly1d/polyder/polyint are replaced by small array helpers.\n//   * matplotlib output is dropped; we log the optimum instead.\n//   * The Python `expand=True` and `ipopt.linear_solver='ma27'` options\n//     are dropped (defaults used; expand crashes the wasm GC teardown).\n\n// Polynomial helpers (coeffs highest-degree-first, like numpy.poly1d).\nfunction polymul(a, b) {\n  const r = new Array(a.length + b.length - 1).fill(0);\n  for (let i = 0; i < a.length; i++)\n    for (let j = 0; j < b.length; j++) r[i + j] += a[i] * b[j];\n  return r;\n}\nfunction polyval(p, x) { let r = 0; for (const c of p) r = r * x + c; return r; }\nfunction polyder(p) {\n  const n = p.length - 1, r = [];\n  for (let i = 0; i < n; i++) r.push(p[i] * (n - i));\n  return r.length ? r : [0];\n}\nfunction polyint(p) {\n  const n = p.length, r = [];\n  for (let i = 0; i < n; i++) r.push(p[i] / (n - i));\n  r.push(0);\n  return r;\n}\n\nasync function example(M, log) {\n  const inf = Infinity;\n\n  // Degree of interpolating polynomial\n  const d = 3;\n\n  // Choose collocation points\n  const tau_root = [0, ...M.collocation_points(d, \"radau\")];\n\n  // Coefficients of the collocation (C), continuity (D), quadrature (F) eqs\n  const C = Array.from({ length: d + 1 }, () => new Array(d + 1).fill(0));\n  const D = new Array(d + 1).fill(0);\n  const Fc = new Array(d + 1).fill(0);\n\n  // Construct polynomial basis\n  for (let j = 0; j <= d; j++) {\n    let p = [1];\n    for (let r = 0; r <= d; r++)\n      if (r !== j) p = polymul(p, [1, -tau_root[r]]).map((c) => c / (tau_root[j] - tau_root[r]));\n    D[j] = polyval(p, 1.0);\n    const pder = polyder(p);\n    for (let r = 0; r <= d; r++) C[j][r] = polyval(pder, tau_root[r]);\n    Fc[j] = polyval(polyint(p), 1.0);\n  }\n\n  // Control discretization\n  const nk = 20;\n  const tf = 10.0;     // End time\n  const h = tf / nk;   // Size of the finite elements\n\n  // Declare variables (use scalar graph)\n  const t = M.SX.sym(\"t\");\n  const u = M.SX.sym(\"u\");\n  const x = M.SX.sym(\"x\", 2);\n  const [x0e, x1e] = M.vertsplit(x);\n\n  // ODE rhs function and quadratures\n  const xdot = M.vertcat(\n    M.plus(M.minus(M.times(M.minus(1, M.times(x1e, x1e)), x0e), x1e), u),\n    x0e);\n  const qdot = M.plus(M.plus(M.times(x0e, x0e), M.times(x1e, x1e)), M.times(u, u));\n  const f = new M.Function(\"f\", [t, x, u], [xdot, qdot], [\"t\", \"x\", \"u\"], [\"xdot\", \"qdot\"]);\n\n  // Control bounds\n  const u_min = -0.75, u_max = 1.0, u_init = 0.0;\n\n  // State bounds and initial guess\n  const x_min = [-inf, -inf], x_max = [inf, inf];\n  const xi_min = [0.0, 1.0], xi_max = [0.0, 1.0];\n  const xf_min = [0.0, 0.0], xf_max = [0.0, 0.0];\n  const x_init = [0.0, 0.0];\n\n  const nx = 2, nu = 1;\n\n  // Total number of variables\n  const NX = nk * (d + 1) * nx;  // Collocated states\n  const NU = nk * nu;            // Parametrized controls\n  const NXF = nx;                // Final state\n  const NV = NX + NU + NXF;\n\n  // NLP variable vector\n  const V = M.MX.sym(\"V\", NV);\n  const Vs = M.vertsplit(V); // scalar entries\n\n  // All variables with bounds and initial guess\n  const vars_lb = new Array(NV).fill(0);\n  const vars_ub = new Array(NV).fill(0);\n  const vars_init = new Array(NV).fill(0);\n  let offset = 0;\n\n  // Get collocated states and parametrized control as MX sub-vectors\n  const X = Array.from({ length: nk + 1 }, () => new Array(d + 1));\n  const U = new Array(nk);\n  const slice = (from, n) => M.vertcat(...Vs.slice(from, from + n));\n  for (let k = 0; k < nk; k++) {\n    for (let j = 0; j <= d; j++) {\n      X[k][j] = slice(offset, nx);\n      vars_init.splice(offset, nx, ...x_init);\n      if (k === 0 && j === 0) {\n        vars_lb.splice(offset, nx, ...xi_min); vars_ub.splice(offset, nx, ...xi_max);\n      } else {\n        vars_lb.splice(offset, nx, ...x_min); vars_ub.splice(offset, nx, ...x_max);\n      }\n      offset += nx;\n    }\n    U[k] = slice(offset, nu);\n    vars_lb[offset] = u_min; vars_ub[offset] = u_max; vars_init[offset] = u_init;\n    offset += nu;\n  }\n  // State at end time\n  X[nk][0] = slice(offset, nx);\n  vars_lb.splice(offset, nx, ...xf_min); vars_ub.splice(offset, nx, ...xf_max);\n  vars_init.splice(offset, nx, ...x_init);\n  offset += nx;\n\n  // Constraints and objective\n  const g = [], lbg = [], ubg = [];\n  let J = M.MX(0);\n\n  for (let k = 0; k < nk; k++) {\n    for (let j = 1; j <= d; j++) {\n      // State derivative at the collocation point\n      let xp_jk = M.times(C[0][j], X[k][0]);\n      for (let r = 1; r <= d; r++) xp_jk = M.plus(xp_jk, M.times(C[r][j], X[k][r]));\n\n      // Collocation equations\n      const Tkj = h * (k + tau_root[j]);\n      const out = f.call([M.DM(Tkj), X[k][j], U[k]]);\n      g.push(M.minus(M.times(h, out[0]), xp_jk));\n      lbg.push(0, 0); ubg.push(0, 0);\n\n      // Objective contribution\n      J = M.plus(J, M.times(Fc[j], M.times(out[1], h)));\n    }\n    // State at the end of the finite element\n    let xf_k = M.times(D[0], X[k][0]);\n    for (let r = 1; r <= d; r++) xf_k = M.plus(xf_k, M.times(D[r], X[k][r]));\n\n    // Continuity equation\n    g.push(M.minus(X[k + 1][0], xf_k));\n    lbg.push(0, 0); ubg.push(0, 0);\n  }\n\n  const G = M.vcat(g);\n  const nlp = { x: V, f: J, g: G };\n  const solver = M.nlpsol(\"solver\", \"ipopt\", nlp);\n\n  const res = solver.call({\n    x0: M.DM(vars_init), lbx: M.DM(vars_lb), ubx: M.DM(vars_ub),\n    lbg: M.DM(lbg), ubg: M.DM(ubg),\n  });\n\n  log(\"-----\");\n  log(\"optimal cost: \" + res[\"f\"].nonzeros().join(\" \"));\n\n  // Get values at the beginning of each finite element\n  const v_opt = res[\"x\"].nonzeros();\n  const stride = (d + 1) * nx + nu;\n  const x0_opt = [], x1_opt = [], u_opt = [];\n  for (let i = 0; i < v_opt.length; i += stride) {\n    x0_opt.push(v_opt[i]);\n    if (i + 1 < v_opt.length) x1_opt.push(v_opt[i + 1]);\n  }\n  for (let i = (d + 1) * nx; i < v_opt.length; i += stride) u_opt.push(v_opt[i]);\n  log(\"x0 trajectory = \" + x0_opt.map((v) => v.toFixed(4)).join(\" \"));\n  log(\"x1 trajectory = \" + x1_opt.map((v) => v.toFixed(4)).join(\" \"));\n  log(\"u  trajectory = \" + u_opt.map((v) => v.toFixed(4)).join(\" \"));\n}\n\nif (typeof require !== \"undefined\" && typeof module !== \"undefined\" && require.main === module) {\n  const path = require(\"path\");\n  const casadiPath = process.env.CASADI_JS\n    || path.resolve(__dirname, \"../../../build-wasm/swig/wasm-js/casadi.js\");\n  require(casadiPath)()\n    .then((M) => example(M, (...a) => console.log(...a)))\n    .catch((e) => { console.error(\"FATAL:\", e.message || e); process.exit(1); });\n}\n\nif (typeof module !== \"undefined\" && module.exports) module.exports = example;\n",
  "vdp_dynamic_programming.js": "//\n//     MIT No Attribution\n//\n//     Copyright (C) 2010-2023 Joel Andersson, Joris Gillis, Moritz Diehl, KU Leuven.\n//\n//     Permission is hereby granted, free of charge, to any person obtaining a copy of this\n//     software and associated documentation files (the \"Software\"), to deal in the Software\n//     without restriction, including without limitation the rights to use, copy, modify,\n//     merge, publish, distribute, sublicense, and/or sell copies of the Software, and to\n//     permit persons to whom the Software is furnished to do so.\n//\n//     THE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED,\n//     INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A\n//     PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT\n//     HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION\n//     OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE\n//     SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.\n//\n//\n// JS port of docs/examples/python/vdp_dynamic_programming.py.\n//\n// Dynamic programming over a discretized state/control grid for the Van der\n// Pol problem. The Python original is pure numpy (no casadi symbolics); this\n// port keeps it as plain JS array math.\n//\n// JS notes (see README.md):\n//   * numpy meshgrid/linspace become flat Float64Array grids.\n//   * matplotlib output is dropped; we log the optimal cost and trajectory.\n\nfunction linspace(a, b, n) {\n  const r = new Array(n);\n  for (let i = 0; i < n; i++) r[i] = a + (b - a) * i / (n - 1);\n  return r;\n}\n\nasync function example(M, log) {\n  const inf = Infinity;\n\n  const T = 10.0;     // End time\n  const N = 20;       // Number of control intervals\n  const NK = 20;      // RK4 steps per interval\n  const DT = T / (N * NK);\n  const NU = 101;     // Number of discrete control values\n  const NX = 101;     // Number of discrete state values per axis\n\n  // System dynamics\n  const f = (x1, x2, u) => [\n    (1 - x2 * x2) * x1 - x2 + u, // x1_dot\n    x1,                          // x2_dot\n    x1 * x1 + x2 * x2 + u * u,   // q_dot\n  ];\n\n  const U = linspace(-1, 1, NU);\n  const x1 = linspace(-1, 1, NX);\n  const x2 = linspace(-1, 1, NX);\n\n  const NG = NX * NX;            // total grid points (row=x2, col=x1)\n  const idx = (i2, i1) => i2 * NX + i1;\n\n  // For each control action, precompute next-state index and stage cost\n  const stage_J = [], next_x1 = [], next_x2 = [];\n  for (let uind = 0; uind < NU; uind++) {\n    const u = U[uind];\n    const nx1 = new Int32Array(NG), nx2 = new Int32Array(NG), Q = new Float64Array(NG);\n    for (let i2 = 0; i2 < NX; i2++) {\n      for (let i1 = 0; i1 < NX; i1++) {\n        let X1 = x1[i1], X2 = x2[i2], Qk = 0;\n        for (let k = 0; k < NK; k++) {\n          const [a1, a2, aq] = f(X1, X2, u);\n          const [b1, b2, bq] = f(X1 + DT / 2 * a1, X2 + DT / 2 * a2, u);\n          const [c1, c2, cq] = f(X1 + DT / 2 * b1, X2 + DT / 2 * b2, u);\n          const [d1, d2, dq] = f(X1 + DT * c1, X2 + DT * c2, u);\n          X1 += DT / 6 * (a1 + 2 * b1 + 2 * c1 + d1);\n          X2 += DT / 6 * (a2 + 2 * b2 + 2 * c2 + d2);\n          Qk += DT / 6 * (aq + 2 * bq + 2 * cq + dq);\n        }\n        // Round to nearest grid index\n        let r1 = Math.round((X1 + 1) / 2 * (NX - 1));\n        let r2 = Math.round((X2 + 1) / 2 * (NX - 1));\n        // Infinite cost if out-of-bounds\n        if (r1 < 0 || r1 >= NX || r2 < 0 || r2 >= NX) { Qk = inf; r1 = 0; r2 = 0; }\n        const g = idx(i2, i1);\n        nx1[g] = r1; nx2[g] = r2; Q[g] = Qk;\n      }\n    }\n    next_x1.push(nx1); next_x2.push(nx2); stage_J.push(Q);\n  }\n\n  // Cost-to-go (no end cost) and optimal control\n  let J = new Float64Array(NG);\n  const U_opt = [];\n  for (let k = N - 1; k >= 0; k--) {\n    const J_prev = new Float64Array(NG).fill(inf);\n    const u_prev = new Int32Array(NG).fill(-1);\n    for (let uind = 0; uind < NU; uind++) {\n      const nx1 = next_x1[uind], nx2 = next_x2[uind], sj = stage_J[uind];\n      for (let g = 0; g < NG; g++) {\n        const test = J[idx(nx2[g], nx1[g])] + sj[g];\n        if (test < J_prev[g]) { J_prev[g] = test; u_prev[g] = uind; }\n      }\n    }\n    J = J_prev;\n    U_opt.push(u_prev);\n  }\n  U_opt.reverse();\n\n  // Optimal control starting at x1=0, x2=1\n  let i1 = Math.floor(NX / 2);\n  let i2 = NX - 1;\n  const u_opt = [], x1_opt = [x1[i1]], x2_opt = [x2[i2]];\n  let cost = 0;\n  for (let k = 0; k < N; k++) {\n    const u_ind = U_opt[k][idx(i2, i1)];\n    cost += stage_J[u_ind][idx(i2, i1)];\n    const ni1 = next_x1[u_ind][idx(i2, i1)], ni2 = next_x2[u_ind][idx(i2, i1)];\n    i1 = ni1; i2 = ni2;\n    u_opt.push(U[u_ind]); x1_opt.push(x1[i1]); x2_opt.push(x2[i2]);\n  }\n\n  log(\"-----\");\n  log(\"Minimal cost: \" + cost);\n  // Consistency check (cf. Python assert)\n  if (Math.abs(cost - J[idx(NX - 1, Math.floor(NX / 2))]) >= 1e-8)\n    throw new Error(\"consistency check failed\");\n  log(\"x1 trajectory = \" + x1_opt.map((v) => v.toFixed(4)).join(\" \"));\n  log(\"x2 trajectory = \" + x2_opt.map((v) => v.toFixed(4)).join(\" \"));\n  log(\"u  trajectory = \" + u_opt.map((v) => v.toFixed(4)).join(\" \"));\n}\n\nif (typeof require !== \"undefined\" && typeof module !== \"undefined\" && require.main === module) {\n  const path = require(\"path\");\n  const casadiPath = process.env.CASADI_JS\n    || path.resolve(__dirname, \"../../../build-wasm/swig/wasm-js/casadi.js\");\n  require(casadiPath)()\n    .then((M) => example(M, (...a) => console.log(...a)))\n    .catch((e) => { console.error(\"FATAL:\", e.message || e); process.exit(1); });\n}\n\nif (typeof module !== \"undefined\" && module.exports) module.exports = example;\n",
  "vdp_indirect_multiple_shooting.js": "//\n//     MIT No Attribution\n//\n//     Copyright (C) 2010-2023 Joel Andersson, Joris Gillis, Moritz Diehl, KU Leuven.\n//\n//     Permission is hereby granted, free of charge, to any person obtaining a copy of this\n//     software and associated documentation files (the \"Software\"), to deal in the Software\n//     without restriction, including without limitation the rights to use, copy, modify,\n//     merge, publish, distribute, sublicense, and/or sell copies of the Software, and to\n//     permit persons to whom the Software is furnished to do so.\n//\n//     THE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED,\n//     INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A\n//     PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT\n//     HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION\n//     OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE\n//     SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.\n//\n//\n// JS port of docs/examples/python/vdp_indirect_multiple_shooting.py.\n//\n// Indirect multiple shooting for the Van der Pol OCP: derive the optimal\n// control from the Hamiltonian, then root-find the node states of the\n// augmented (state, costate) ODE so all shooting gaps close and the\n// state/costate boundary conditions hold.\n//\n// JS notes (see README.md):\n//   * The Python \"cvodes\" integrator aborts the wasm runtime; we substitute\n//     \"rk\". Because each shooting interval is short (tf/num_nodes = 0.5s),\n//     explicit RK integrates the augmented ODE stably here.\n//   * The root-finding problem uses the \"nlpsol\"/\"ipopt\" plugin exactly as\n//     the Python original (its globalization is needed; the plain \"newton\"\n//     root-finder lands on spurious roots, and \"kinsol\" aborts the runtime).\n//   * For the trajectory plot the Python code re-integrates the full 10s in\n//     one shot; under explicit RK that blows up on the unstable costate ODE,\n//     so we instead re-integrate per shooting interval (each stable).\n//   * matplotlib output is dropped; we log the optimum instead.\n\nasync function example(M, log) {\n  // Declare variables\n  const x0 = M.SX.sym(\"x0\"), x1 = M.SX.sym(\"x1\");\n  const x = M.vertcat(x0, x1);\n\n  // Control\n  const u = M.SX.sym(\"u\");\n\n  // ODE right hand side\n  const xdot = M.vertcat(\n    M.plus(M.minus(M.times(M.minus(1, M.times(x1, x1)), x0), x1), u),\n    x0);\n\n  // Lagrangian\n  const L = M.plus(M.plus(M.times(x0, x0), M.times(x1, x1)), M.times(u, u));\n\n  // Costate\n  const lam = M.SX.sym(\"lam\", 2);\n\n  // Hamiltonian\n  const H = M.plus(M.dot(lam, xdot), L);\n\n  // Costate equations\n  const ldot = M.times(-1, M.gradient(H, x));\n\n  log(\"Hamiltonian: \" + H.str());\n\n  // H is convex quadratic in u: H = u*u + p*u + q; extract p\n  let p = M.gradient(H, u);\n  p = M.substitute(p, u, M.SX(0));\n\n  // Unconstrained minimizer u = -p/2, clipped to [-0.75, 1.0]\n  let u_opt = M.times(-0.5, p);\n  u_opt = M.fmin(u_opt, M.SX(1.0));\n  u_opt = M.fmax(u_opt, M.SX(-0.75));\n  log(\"optimal control: \" + u_opt.str());\n\n  // Augment f with ldot and substitute the optimal control\n  let f = M.vertcat(xdot, ldot);\n  f = M.substitute(f, u, u_opt);\n\n  // Function for the optimal control given the augmented state\n  const xlam = M.vertcat(x, lam);\n  const u_fcn = new M.Function(\"ufcn\", [xlam], [u_opt]);\n\n  // DAE for the augmented dynamics\n  const dae = { x: xlam, ode: f };\n\n  const nX = 4;              // augmented state dimension\n  const tf = 10.0;          // end time\n  const num_nodes = 20;     // shooting nodes\n\n  // Integrator over one interval -- \"rk\" stands in for \"cvodes\"\n  const I = M.integrator(\"I\", \"rk\", dae, 0, tf / num_nodes, { number_of_finite_elements: 50 });\n\n  // States at each shooting node (4 x (num_nodes+1))\n  const X = M.MX.sym(\"X\", nX, num_nodes + 1);\n  const Xc = M.horzsplit(X); // columns X[:,k]\n\n  // Root finding problem\n  const G = [];\n  // states fixed, costates free at initial time\n  G.push(M.minus(M.vertcat(...M.vertsplit(Xc[0]).slice(0, 2)), M.MX([0, 1])));\n  for (let k = 0; k < num_nodes; k++) {\n    const XF = I.call({ x0: Xc[k] })[\"xf\"];\n    G.push(M.minus(XF, Xc[k + 1]));\n  }\n  // costates fixed, states free at final time\n  G.push(M.minus(M.vertcat(...M.vertsplit(Xc[num_nodes]).slice(2, 4)), M.MX([0, 0])));\n\n  // Root-finding problem (vectorize X)\n  const rfp = new M.Function(\"rfp\", [M.vec(X)], [M.vcat(G)]);\n\n  // Solver: \"nlpsol\"/\"ipopt\" exactly as in the Python original\n  const solver = M.rootfinder(\"solver\", \"nlpsol\", rfp, {\n    nlpsol: \"ipopt\",\n    nlpsol_options: {\n      \"ipopt.hessian_approximation\": \"limited-memory\",\n      \"ipopt.print_level\": 0,\n      print_time: false,\n    },\n  });\n\n  // Solve\n  const X_sol = solver.call([M.DM.zeros(nX * (num_nodes + 1))])[0];\n  log(\"node-state solution (4 x \" + (num_nodes + 1) + \"):\");\n  log(\"X_sol = \" + X_sol.nonzeros().map((v) => v.toFixed(4)).join(\" \"));\n\n  // Visualize per-node (each 0.5s interval is stable under explicit RK; a\n  // single 10s re-integration would blow up on the unstable costate ODE).\n  const per = 5; // sub-samples per shooting interval\n  const tgrid_node = [];\n  for (let i = 0; i <= per; i++) tgrid_node.push((tf / num_nodes) * i / per);\n  const vis = M.integrator(\"vis\", \"rk\", dae, 0, tgrid_node, { number_of_finite_elements: 20 });\n  const nz = X_sol.nonzeros();\n  const x_traj = [], y_traj = [], u_list = [], tgrid = [];\n  for (let k = 0; k < num_nodes; k++) {\n    const xk = M.DM(nz.slice(k * nX, k * nX + nX));\n    const seg = vis.call({ x0: xk })[\"xf\"].nonzeros(); // 4 x per\n    for (let c = 0; c < per; c++) {\n      const xa = seg.slice(c * nX, c * nX + nX);\n      x_traj.push(xa[0]); y_traj.push(xa[1]);\n      u_list.push(u_fcn.call([M.DM(xa)])[0].nonzeros()[0]);\n      tgrid.push(k * (tf / num_nodes) + tgrid_node[c]);\n    }\n  }\n\n  log(\"-----\");\n  log(\"x trajectory = \" + x_traj.map((v) => v.toFixed(4)).join(\" \"));\n  log(\"y trajectory = \" + y_traj.map((v) => v.toFixed(4)).join(\" \"));\n  log(\"u trajectory = \" + u_list.map((v) => v.toFixed(4)).join(\" \"));\n}\n\nif (typeof require !== \"undefined\" && typeof module !== \"undefined\" && require.main === module) {\n  const path = require(\"path\");\n  const casadiPath = process.env.CASADI_JS\n    || path.resolve(__dirname, \"../../../build-wasm/swig/wasm-js/casadi.js\");\n  require(casadiPath)()\n    .then((M) => example(M, (...a) => console.log(...a)))\n    .catch((e) => { console.error(\"FATAL:\", e.message || e); process.exit(1); });\n}\n\nif (typeof module !== \"undefined\" && module.exports) module.exports = example;\n"
};
